(window.DEEP=window.DEEP||{})['lt']={"T":{"lt-01":"Literary Theory 1: يعني إيه نقد أدبي؟","lt-02":"Literary Theory 2: تاريخ النقد قبل القرن العشرين","lt-03":"Literary Theory 3: خريطة مدارس القرن العشرين","lt-04":"Literary Theory 4: النقد التاريخي والسيري","lt-05":"Literary Theory 5: تطبيق النقد التاريخي على Ozymandias","lt-06":"Literary Theory 6: تطبيق النقد التاريخي على Hamlet","lt-07":"Literary Theory 7: التاريخانية الجديدة","lt-08":"Literary Theory 8: الشكلانية الروسية والإنجليزية","lt-09":"Literary Theory 9: النقد الجديد","lt-10":"Literary Theory 10: صندوق أدوات القراءة المتأنية","lt-11":"Literary Theory 11: قراءة شكلية لـ Ozymandias","lt-12":"Literary Theory 12: قراءة شكلية لـ Hamlet","lt-13":"Literary Theory 13: استجابة القارئ، روزنبلات وإيزر","lt-14":"Literary Theory 14: هولاند وبلايش وفيش","lt-15":"Literary Theory 15: استجابة القارئ تطبيقاً على Ozymandias","lt-16":"Literary Theory 16: فرويد والتحليل النفسي","lt-17":"Literary Theory 17: يونغ واللاوعي الجمعي","lt-18":"Literary Theory 18: تطبيق التحليل النفسي، هاملت وMurderball","lt-19":"Literary Theory 19: الدراسات الثقافية، ما هي؟","lt-20":"Literary Theory 20: المادية الثقافية البريطانية والهيمنة","lt-21":"Literary Theory 21: التعددية الثقافية الأمريكية","lt-22":"Literary Theory 22: الدراسات الثقافية تطبيقاً على Hamlet","lt-23":"Literary Theory 23: النقد النسوي، التعريف والتاريخ","lt-24":"Literary Theory 24: اتجاهات النقد النسوي المعاصر","lt-25":"Literary Theory 25: قراءة نسوية لـ Hamlet","lt-26":"Literary Theory 26: مقارنة كل المدارس ومقالات الامتحان"},"P":[{"i":"lt-01","s":1,"h":"مقدمة: يعني إيه نقد أدبي؟","t":"learn","x":"تخيل الموقف ده صاحبك قرأ قصيدة وقال \"حلوة\". وإنت قرأت نفس القصيدة وقلت \"مملة\". مين فيكم صح؟ الإجابة: ولا حد، لحد ما كل واحد يقول why أي ليه. والنقد الأدبي هو العلم اللي بيعلمك تقول ليه."},{"i":"lt-01","s":2,"h":"مقدمة: يعني إيه نقد أدبي؟","t":"learn","x":"التعريف النقد الأدبي literary criticism هو دراسة الأدب وتفسيره وتقييمه. يعني الناقد بيعرف العمل، ويصنفه، ويفسر معناه، وبعدين يحكم عليه بدليل. Literary criticism is the study, interpretation and evaluation of literature."},{"i":"lt-01","s":3,"h":"مقدمة: يعني إيه نقد أدبي؟","t":"mc","x":"النقد الأدبي هو: ؟ قراءة القصيدة لمجرد المتعة / دراسة الأدب وتفسيره وتقييمه / حفظ تواريخ الأدباء / كتابة قصيدة جديدة . النقد يدرس العمل ويفسره ويقيمه بدليل."},{"i":"lt-01","s":5,"h":"النظرية والتطبيق","t":"learn","x":"النظرية زي الخريطة النظرية theory هي مجموعة مبادئ ومصطلحات عامة نفهم بيها الأدب. تخيلها خريطة مدينة. والتطبيق practice هو إنك تمشي بالخريطة دي جوه نص معين. لما النظرية تتطبق على عمل أدبي بيبقى اسمها نقد."},{"i":"lt-01","s":6,"h":"النظرية والتطبيق","t":"learn","x":"مثال بسيط النظرية بتقول: literature reflects society أي الأدب بيعكس المجتمع. التطبيق: نقرأ قصيدة London للشاعر William Blake ونشوف فيها الفقر والظلم اللي كان في لندن زمنه. النظرية بتفسر التطبيق، والتطبيق بيختبر النظرية. الاتنين بيعتمدوا على بعض."},{"i":"lt-01","s":7,"h":"النظرية والتطبيق","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ النقد الجديد والتاريخانية الجديدة متفقان على قراءة النص بمعزل عن التاريخ. / أفلاطون وأرسطو كان رأيهم واحد تماما في الشعر. / لما نطبق نظرية على نص معين، بنسمي ده تطبيق (practice). / الدراسات الأدبية في التعددية الثقافية تتفق على إجابة واحدة لمن يقرر أي ثقافات تدخل المنهج. . التطبيق هو استخدام النظرية على نص حقيقي."},{"i":"lt-01","s":9,"h":"ليه نحتاج الناقد؟","t":"learn","x":"الناقد بيشوف اللي إحنا مش شايفينه الناقد الجيد يوصل لتحت السطور، ويلاحظ حاجات بتعدي من غير ما حد ياخد باله. وبيعلمنا ثلاث حاجات: نقرأ بذكاء، ونقدر الجمال في العمل، ونحكم عليه بأسباب مش بمزاج."},{"i":"lt-01","s":10,"h":"ليه نحتاج الناقد؟","t":"learn","x":"النظريات زي النضارات كل مدرسة نقدية school of criticism زي نضارة بلون مختلف. نفس النص، وكل نضارة بتوريك حاجة. وجود أكتر من تفسير للنص الواحد قوة مش ضعف، لأنه بيخلينا نشوف الصورة كاملة. Theories are lenses. One text, many readings."},{"i":"lt-01","s":12,"h":"العائلات التلاتة","t":"learn","x":"تقسيم كبير المدارس النقدية الكبيرة بتتقسم تلات عائلات حسب اللي بتركز عليه. العائلة الأولى: الشكلية formal . بتركز على بنية النص نفسه: الشكلانية formalism ، والبنيوية structuralism ، والتفكيكية deconstruction ."},{"i":"lt-01","s":13,"h":"العائلات التلاتة","t":"learn","x":"العائلة التانية والتالتة العائلة التانية: الاجتماعية social . بتربط النص بالمجتمع: التاريخانية الجديدة new historicism ، والنسوية feminism ، والماركسية Marxism . العائلة التالتة: الشخصية personal . بتركز على العقل والتجربة الفردية للمؤلف أو القارئ: التحليل النفسي psychoanalytic criticism واستجابة القارئ reader-response ."},{"i":"lt-01","s":14,"h":"العائلات التلاتة","t":"mc","x":"أي مدرسة من العائلة الاجتماعية (social)؟ ؟ البنيوية / التحليل النفسي / النسوية / استجابة القارئ . النسوية بتقرأ النص في علاقته بالمجتمع وصورة المرأة فيه."},{"i":"lt-01","s":15,"h":"العائلات التلاتة","t":"learn","x":"جرب بنفسك: جملة واحدة وتلات عدسات الجملة: \"الشارع كان فاضي\". بعدسة شكلية: نلاحظ الكلمات والإيقاع. بعدسة اجتماعية: ليه فاضي؟ حظر؟ فقر؟ هجرة؟ بعدسة نفسية: يمكن الفراغ بيعبر عن إحساس الراوي بالوحدة."},{"i":"lt-01","s":16,"h":"العائلات التلاتة","t":"learn","x":"ملحوظة مهمة النقد مش رأي عشوائي. أي حكم لازم يتسند على دليل من النص نفسه، زي كلمة أو سطر أو مشهد. كمان استخدم عبارات حذرة زي many readers say لما يبقى التفسير اجتهاد."},{"i":"lt-01","s":17,"h":"العائلات التلاتة","t":"mc","x":"أي دليل يصلح لتفسير نقدي مقبول؟ ؟ شعوري الشخصي من غير أي نص / سطر من النص أستشهد بيه / شهرة الكاتب / عدد صفحات الكتاب . الاستشهاد بسطر أو مشهد من النص هو أساس الحجة النقدية."},{"i":"lt-01","s":18,"h":"العائلات التلاتة","t":"learn","x":"الملخص النقد الأدبي: دراسة وتفسير وتقييم. النظرية خريطة، والتطبيق مشي بالخريطة على نص. المدارس عدسات، وبتتقسم: شكلية، اجتماعية، شخصية. وكل حكم لازم يتسند لدليل من النص."},{"i":"lt-01","s":19,"h":"العائلات التلاتة","t":"recall","x":"اذكر العائلات التلاتة للمدارس النقدية وهات مدرسة من كل عائلة. . شكلية (formal) مثل البنيوية. اجتماعية (social) مثل النسوية. شخصية (personal) مثل التحليل النفسي."},{"i":"lt-01","s":20,"h":"العائلات التلاتة","t":"write","x":"على نمط امتحانات الكلية: وضح الفرق بين النظرية الأدبية والنقد الأدبي مع مثال (من 4 إلى 5 جمل). . النظرية الأدبية هي مجموعة مبادئ ومصطلحات عامة نفهم بيها الأدب، مثل مبدأ أن الأدب يعكس المجتمع. أما النقد فهو تطبيق النظرية على عمل معين، مثل قراءة قصيدة London لبليك لنكشف الظلم الاجتماعي في لندن. النظرية تفسر الممارسة، والممارسة تختبر النظرية، فالاتنين يتفاعلوا مع بعض."},{"i":"lt-02","s":1,"h":"مقدمة","t":"learn","x":"النقد أقدم من الروايات قبل ما تتكتب أول رواية حديثة بآلاف السنين، كان فيه ناس بتتخانق على قيمة الشعر. وأولهم كانوا اليونان القدماء. في الدرس ده هنمشي على خط زمني بسيط من اليونان لحد القرن التاسع عشر."},{"i":"lt-02","s":3,"h":"اليونان والرومان","t":"learn","x":"أفلاطون Plato (حوالي 428 إلى 348 قبل الميلاد) أفلاطون شاف إن الشعر imitation أي تقليد للعالم الحقيقي، والعالم الحقيقي نفسه عنده صورة ناقصة، فالشعر تقليد للتقليد. وكان خايف إن الشعر يلعب بمشاعر الناس. علشان كده قال في كتابه The Republic إن الشعراء مكانهم مش في المدينة المثالية."},{"i":"lt-02","s":4,"h":"اليونان والرومان","t":"learn","x":"أرسطو Aristotle (384 إلى 322 قبل الميلاد) أرسطو كان تلميذ أفلاطون، واختلف معاه. في كتابه Poetics قال إن التقليد حاجة طبيعية عند الإنسان، وإن الأدب بيعلم. وقال إن المأساة tragedy بتعمل catharsis أي تطهير للمشاعر: نخاف ونشفق وإحنا قاعدين في الأمان، فنطلع أخف. وإن الحبكة plot أهم عناصر المأساة."},{"i":"lt-02","s":5,"h":"اليونان والرومان","t":"mc","x":"مين اللي ربط المأساة بفكرة التطهير (catharsis)؟ ؟ أفلاطون / أرسطو / وردزورث / تين . أرسطو في كتاب Poetics."},{"i":"lt-02","s":6,"h":"اليونان والرومان","t":"learn","x":"هوراس Horace (65 إلى 8 قبل الميلاد) الشاعر الروماني هوراس لخص وظيفة الأدب في عبارة شهيرة: الأدب لازم يمتع ويفيد. بالإنجليزي: to delight and to instruct . واللاتيني: dulce et utile ."},{"i":"lt-02","s":7,"h":"اليونان والرومان","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ أنهي جملة من دول صحيحة؟ / أفلاطون وأرسطو كان رأيهم واحد تماما في الشعر. / الأسئلة مفتوحة وخلافية. / استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. . أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته."},{"i":"lt-02","s":9,"h":"من عصر النهضة للرومانسية","t":"learn","x":"فيليب سيدني Philip Sidney في عصر النهضة الإنجليزي كتب سيدني The Defence of Poesy ، وده دفاع عن الشعر ضد اللي كانوا بيهاجموه. اتنشر سنة 1595. وقال إن الشعر بيعلم وبيمتع أكتر من التاريخ والفلسفة."},{"i":"lt-02","s":10,"h":"من عصر النهضة للرومانسية","t":"learn","x":"العصر الكلاسيكي الجديد Neoclassical في القرن السابع عشر والثامن عشر، الناس حبت النظام والعقل والقواعد. أشهر النقاد: John Dryden و Alexander Pope و Samuel Johnson . كتير بيقولوا إن دريدن هو أبو النقد الإنجليزي."},{"i":"lt-02","s":11,"h":"من عصر النهضة للرومانسية","t":"learn","x":"الرومانسيون Romantics William Wordsworth كتب مقدمة لديوان Lyrical Ballads (الديوان طلع سنة 1798 والمقدمة الشهيرة في طبعة 1800). قال إن الشعر هو the spontaneous overflow of powerful feelings أي فيضان تلقائي من المشاعر القوية. يعني الأهم عندهم الإحساس والخيال مش القواعد."},{"i":"lt-02","s":12,"h":"من عصر النهضة للرومانسية","t":"mc","x":"العبارة \"the spontaneous overflow of powerful feelings\" لمين؟ ؟ دريدن / هوراس / وردزورث / أرسطو . وردزورث في مقدمة Lyrical Ballads."},{"i":"lt-02","s":14,"h":"القرن التاسع عشر","t":"learn","x":"ماثيو أرنولد Matthew Arnold ناقد إنجليزي فيكتوري، آمن إن الأدب العظيم بيساعد الناس أخلاقيا وفكريا. ومن أشهر عباراته إن الشعر a criticism of life أي نقد للحياة. وكان شايف إن مهمة الناقد إنه يعرفنا the best that has been thought and said أي أفضل ما قيل وفكر فيه."},{"i":"lt-02","s":15,"h":"القرن التاسع عشر","t":"learn","x":"هيبوليت تين Hippolyte Taine ناقد فرنسي قال إن العمل الأدبي بيتشكل من ثلاث حاجات: race و milieu و moment ، يعني الجماعة اللي ينتمي ليها الكاتب والبيئة المحيطة واللحظة التاريخية. فكرته دي هي جذر النقد التاريخي والسيري اللي هندرسه بعد كده."},{"i":"lt-02","s":16,"h":"القرن التاسع عشر","t":"mc","x":"أي ثلاثية ارتبطت بتين؟ ؟ race و milieu و moment / plot و character و setting / delight و instruct و imitate / id و ego و superego . الثلاثية دي نظرية تين في تفسير العمل الأدبي."},{"i":"lt-02","s":17,"h":"القرن التاسع عشر","t":"learn","x":"لحد هنا وبعدين إيه؟ في القرن العشرين النقد بقى مدارس منظمة ليها كتب ومصطلحات. وبسبب كده سموه the Age of Criticism أي عصر النقد. الدرس الجاي نشوف خريطة المدارس دي كلها."},{"i":"lt-02","s":18,"h":"القرن التاسع عشر","t":"learn","x":"الملخص أفلاطون: الشعر تقليد وخطر. أرسطو: تطهير وحبكة. هوراس: يمتع ويفيد. سيدني: دفاع عن الشعر. دريدن وبوب وجونسون: نظام وقواعد. وردزورث: مشاعر. أرنولد: نقد للحياة. تين: race وmilieu وmoment."},{"i":"lt-02","s":19,"h":"القرن التاسع عشر","t":"recall","x":"قارن باختصار بين أفلاطون وأرسطو في موقفهما من الشعر. . أفلاطون شاف الشعر تقليدا للتقليد وخطرا على المشاعر. أرسطو شاف التقليد طبيعيا ومفيدا، وقال إن المأساة تعمل تطهيرا وإن الحبكة أهم عنصر فيها."},{"i":"lt-02","s":20,"h":"القرن التاسع عشر","t":"write","x":"على نمط امتحانات الكلية: لخص تطور النقد الأدبي من العصور القديمة حتى القرن التاسع عشر (من 5 إلى 6 جمل). . بدأ النقد عند اليونان مع أفلاطون الذي خاف من الشعر ومع أرسطو الذي دافع عنه وتحدث عن التطهير والحبكة. أضاف هوراس أن الأدب يمتع ويفيد. في عصر النهضة دافع سيدني عن الشعر. ثم أعلى العصر الكلاسيكي الجديد قيمة العقل والقواعد، وجاء الرومانسيون مع وردزورث ليقدموا المشاعر. وفي العصر الفيكتوري رأى أرنولد أن الأدب نقد للحياة، وقدم تين فكرة race وmilieu وmoment التي مهدت للنقد التاريخي."},{"i":"lt-03","s":1,"h":"مقدمة","t":"learn","x":"جولة سريعة في مدينة النقد النهاردة هنعدي على كل مدارس القرن العشرين بشكل سريع، زي جولة بالأتوبيس. بعد كده كل مدرسة ليها دروسها."},{"i":"lt-03","s":3,"h":"العائلة الشكلية","t":"learn","x":"الشكلانية Formalism بدأت في إنجلترا مع I. A. Richards وكتابه Practical Criticism سنة 1929. كان بيدي الطلبة قصايد من غير اسم الشاعر علشان يقروا النص نفسه ومش يتأثروا بالشهرة. الفكرة: النص كيان مستقل. السيرة والتاريخ ورد فعل القارئ مش هي اللي بتحدد المعنى."},{"i":"lt-03","s":4,"h":"العائلة الشكلية","t":"learn","x":"البنيوية Structuralism جذورها في علم اللغة والأنثروبولوجيا. بتشوف الأدب system of signs أي نظام علامات، والمعنى بييجي من علاقة العلامات ببعض. Ferdinand de Saussure قال في Course in General Linguistics (1916) إن العلاقة بين الكلمة والشيء اعتباطية. كلمة cat عندنا و chat عند الفرنسيين، والاتنين بيدلوا على نفس الحيوان."},{"i":"lt-03","s":5,"h":"العائلة الشكلية","t":"learn","x":"التفكيكية Deconstruction جت كرد فعل على يقين البنيوية. الفيلسوف الفرنسي Jacques Derrida شاف إن النص بيحمل جواه حاجة بتهز معناه الظاهر. فمفيش معنى نهائي، وكل معنى مؤقت. ولاحظ إن التفكيكيين زي البنيويين بيركزوا على النص وبعيد عن سيرة الكاتب."},{"i":"lt-03","s":6,"h":"العائلة الشكلية","t":"mc","x":"أي مدرسة بتقول إن النص ممكن يهدم معناه بنفسه؟ ؟ الشكلانية / التفكيكية / الماركسية / النسوية . التفكيكية بتشوف إن النص غير مستقر وبيحمل ما يناقضه."},{"i":"lt-03","s":8,"h":"العائلة الاجتماعية","t":"learn","x":"المدرسة الاجتماعية Sociological criticism بتقول إن العمل الأدبي لا ينفصل عن المجتمع اللي اتكتب فيه، وبتسأل: ليه اتكتب النص ده؟ وبيرد على أي موقف اجتماعي؟ وأقوى فرعين فيها في القرن العشرين: الماركسية والنسوية."},{"i":"lt-03","s":9,"h":"العائلة الاجتماعية","t":"learn","x":"النسوية Feminist criticism بدأت كمنهج واضح في أواخر الستينات. هي مبادئ أكتر منها تقنية معينة. بتسأل: إزاي اتصورت المرأة في النصوص؟ وبتدور على كاتبات اتنسوا علشان تعيد اكتشافهم."},{"i":"lt-03","s":10,"h":"العائلة الاجتماعية","t":"learn","x":"الماركسية Marxist criticism قائمة على أفكار Karl Marx و Friedrich Engels عن الطبقات والاقتصاد. بتقرأ الأدب كجزء من الصراع بين الطبقات. وترى إن الأدب لازم يساهم في تحسين حياة المجتمع."},{"i":"lt-03","s":11,"h":"العائلة الاجتماعية","t":"learn","x":"التاريخانية الجديدة New Historicism ظهرت في الجامعات الأمريكية في الثمانينات، وبدأت مع Stephen Greenblatt وكتابه Renaissance Self-Fashioning (1980). بتشوف إن الأدب والتاريخ بيشكلوا بعض، ومش بتفرق بين نص أدبي وغير أدبي. كل النصوص عندها cultural artifacts أي منتجات ثقافية."},{"i":"lt-03","s":12,"h":"العائلة الاجتماعية","t":"mc","x":"التاريخانية الجديدة ظهرت أولا في: ؟ أمريكا في الثمانينات / فرنسا في الثلاثينات / روسيا في بداية القرن / بريطانيا في العصر الفيكتوري . ظهرت في الجامعات الأمريكية في الثمانينات."},{"i":"lt-03","s":14,"h":"العائلة الشخصية","t":"learn","x":"التحليل النفسي Psychoanalytic criticism بيشوف العمل الأدبي تعبير عن العقل الداخلي. طوره Sigmund Freud (1856 إلى 1939) اللي قال إن أغلب سلوكنا مش واعي، وإننا نكبت رغبات علشان نعيش مع الناس. وبعده Jacques Lacan (1901 إلى 1981) ربط فرويد بالبنيوية، وقال إن دخول اللغة هو دخول الإنسان العالم الاجتماعي."},{"i":"lt-03","s":15,"h":"العائلة الشخصية","t":"learn","x":"استجابة القارئ Reader-response criticism ثورة على الشكلانية. بتقول إن المعنى مش جوه النص وبس، المعنى بيتولد من تفاعل القارئ مع النص. كل قارئ بيجيب تجاربه ومعرفته، فلكل قارئ تجربة فريدة، وده بيفسر اختلاف التفسيرات."},{"i":"lt-03","s":16,"h":"العائلة الشخصية","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ التضمين (enjambment) موجود في القصيدة ويخلق توترا. / المغالطة القصدية بتقول إن النية مش متاحة ومش مطلوبة كمعيار. / استجابة القارئ بتقول إن المعنى كله موجود جوه النص ولا يتأثر بالقارئ. / التضمين هو استمرار المعنى للسطر التالي بدون وقف. . استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص."},{"i":"lt-03","s":17,"h":"العائلة الشخصية","t":"learn","x":"جدول المقارنة السريع الشكلانية: النص، القراءة المتأنية. البنيوية: النظام والعلامات. التفكيكية: عدم الاستقرار. الماركسية: الطبقة. النسوية: الجندر. التاريخانية الجديدة: الثقافة والسلطة. التحليل النفسي: اللاوعي. استجابة القارئ: القارئ."},{"i":"lt-03","s":18,"h":"العائلة الشخصية","t":"mc","x":"أي مطابقة بين الاسم والمدرسة غلط؟ ؟ Greenblatt والتاريخانية الجديدة / Derrida والتفكيكية / Freud والتحليل النفسي / Saussure والنسوية . سوسير ارتبط بالبنيوية وعلم اللغة، مش بالنسوية."},{"i":"lt-03","s":19,"h":"العائلة الشخصية","t":"learn","x":"الملخص شكلية: الشكلانية والبنيوية والتفكيكية. اجتماعية: الماركسية والنسوية والتاريخانية الجديدة. شخصية: التحليل النفسي واستجابة القارئ."},{"i":"lt-03","s":20,"h":"العائلة الشخصية","t":"recall","x":"قارن في جملتين بين الشكلانية واستجابة القارئ. . الشكلانية ترى أن المعنى في النص نفسه وأن القارئ والسيرة غير مهمين. استجابة القارئ ترى أن المعنى يتكون من تفاعل القارئ مع النص، ولهذا تختلف القراءات."},{"i":"lt-03","s":21,"h":"العائلة الشخصية","t":"write","x":"على نمط امتحانات الكلية: قارن بين البنيوية والتفكيكية (من 4 إلى 5 جمل). . كلتاهما تهتم بالنص وتبتعد عن سيرة الكاتب. البنيوية ترى النص نظام علامات له بنية يمكن اكتشافها، مستندة إلى سوسير. أما التفكيكية، مع دريدا، فترى أن النص يحمل ما يناقض معناه فلا يستقر على معنى نهائي. فالأولى تبحث عن النظام والثانية تكشف عدم الاستقرار."},{"i":"lt-04","s":1,"h":"مقدمة","t":"learn","x":"سؤال بسيط هل ينفع تفهم قصيدة من غير ما تعرف مين كتبها ولا في أي زمن؟ المدرسة اللي هنتعلمها النهاردة بتقول: لأ، لازم تعرف. اسمها النقد التاريخي والسيري Historical-Biographical Criticism ، وبتتسمى كمان النقد التقليدي Traditional Criticism ."},{"i":"lt-04","s":3,"h":"الفكرة الأساسية","t":"learn","x":"الأدب مرآة لحياة كاتبه وزمنه النقد التاريخي والسيري بيشوف الأدب انعكاسا لحياة المؤلف وعصره، أو حياة الشخصيات وعصرها. علشان نفهم العمل صح، لازم نعرف السياق السياسي والاقتصادي والاجتماعي اللي اتكتب فيه."},{"i":"lt-04","s":4,"h":"الفكرة الأساسية","t":"learn","x":"الفن مش بيعيش في فراغ العمل الأدبي اتكتب على إيد حد معين، في وقت معين، وبيكلم ناس معينة عن فكرة أو مشكلة تهمهم. فمن الخطر نعامله كأنه منفصل عن أي تجربة إنسانية ونقيمه بس بالاستعارة والتوتر والغموض."},{"i":"lt-04","s":5,"h":"الفكرة الأساسية","t":"mc","x":"الفكرة الأساسية للنقد التاريخي والسيري إن: ؟ النص لازم يتفهم من غير أي سياق / الأدب انعكاس لحياة المؤلف وعصره / القارئ هو اللي بيصنع المعنى وحده / النص نظام علامات مالوش مؤلف . المدرسة دي بتربط العمل بحياة كاتبه وزمنه."},{"i":"lt-04","s":7,"h":"تين وجذور المدرسة","t":"learn","x":"هيبوليت تين Hippolyte Taine أوضح من عبر عن مبادئ المدرسة دي هو الناقد الفرنسي هيبوليت تين في القرن التاسع عشر. فكرته: العمل الأدبي نتاج race و milieu و moment . يعني الجماعة اللي جه منها الكاتب، والبيئة اللي عاش فيها، واللحظة التاريخية."},{"i":"lt-04","s":8,"h":"تين وجذور المدرسة","t":"learn","x":"الشعراء مش بعيدين عن السياسة غلط نفتكر إن الشعراء مبيهتموش بالقضايا الاجتماعية والسياسية. على مر العصور كان الأدباء مؤرخين ومفسرين لثقافة زمنهم. أمثلة: The Canterbury Tales لتشوسر، ومسرحيات شكسبير، ورواية Wuthering Heights لإميلي برونتي."},{"i":"lt-04","s":9,"h":"تين وجذور المدرسة","t":"learn","x":"مثال من بليك William Blake كتب قصيدة London . كتير من قصايده مبتتفهمش صح إلا لو عرفت إنجلترا في زمنه. القصيدة صرخة ضد ظلم المجتمع للإنسان: الفقر وعمالة الأطفال وسلطة الكنيسة والملك."},{"i":"lt-04","s":10,"h":"تين وجذور المدرسة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ حسب النقد التاريخي، ينفع نفهم أي عمل أدبي كويس من غير ما نعرف شيء عن زمنه. / النقد الجديد يفصل النص، والتاريخانية الجديدة تربطه بالثقافة. / حسب القراءة التاريخية، شيلي كتب القصيدة بعد حكاية عن رمسيس الثاني المصري. / حسب هذه القراءة، فكرة الانتخاب تساعد على تفسير أن هاملت ما أخدش العرش بعد موت أبيه. . النقد التاريخي بيشترط معرفة السياق التاريخي والاجتماعي."},{"i":"lt-04","s":12,"h":"إيه الأسئلة اللي بيسألها الناقد؟","t":"learn","x":"أسئلة الناقد التاريخي من هو المؤلف وإيه ظروف حياته؟ في أي زمن كتب العمل؟ إيه الأحداث السياسية والاجتماعية وقتها؟ إيه العادات والمعتقدات اللي كان الجمهور بيعرفها؟ وبعدين نستخدم الإجابات علشان نفهم كلمة أو مشهد أو شخصية."},{"i":"lt-04","s":13,"h":"إيه الأسئلة اللي بيسألها الناقد؟","t":"learn","x":"مثال بسيط من حياتك لو قريت جملة \"الغلاء بيخنق الناس\" في جريدة، هتفهمها غير لو معرفتش إن الجريدة اتكتبت وقت أزمة اقتصادية. نفس الفكرة: السياق بيغير الفهم."},{"i":"lt-04","s":15,"h":"حدود المدرسة","t":"learn","x":"النقد الأدبي يتحول لسيرة وتاريخ من أكبر الانتقادات إن الاعتماد الزائد على السيرة والتاريخ ممكن يحول دراسة الأدب إلى دراسة سيرة أو تاريخ، وننسى جمال النص نفسه. كمان ممكن نفترض غلط إن كل شخصية في العمل هي الكاتب نفسه، والأدب فيه خيال."},{"i":"lt-04","s":16,"h":"حدود المدرسة","t":"learn","x":"رد على النقد مؤيدو المدرسة يقولوا: مفيش مشكلة نفهم النص من السياق طالما مش بنهمل شكله. الفن بيخاطب بشر في زمن معين، فتجاهل ده خطأ. والمدارس الشكلية اللي هنتعلمها بعد كده ظهرت أصلا كرد فعل على الاعتماد الزائد على السيرة والتاريخ."},{"i":"lt-04","s":17,"h":"حدود المدرسة","t":"mc","x":"أبرز نقد موجه للنقد التاريخي والسيري هو: ؟ إنه بيهمل القارئ دايما / إنه ممكن يحول الأدب لدراسة سيرة وتاريخ وينسى النص / إنه بيرفض أي معلومة عن الكاتب / إنه بيعتمد على الخرافة . الانتقاد الأشهر هو الانشغال بالسيرة والتاريخ على حساب النص."},{"i":"lt-04","s":18,"h":"حدود المدرسة","t":"learn","x":"الملخص النقد التاريخي والسيري: الأدب انعكاس لحياة الكاتب وزمنه. تين: race وmilieu وmoment. الأسئلة: مين الكاتب؟ أي زمن؟ أي سياق؟ والحدود: خطر تحويل الأدب لسيرة وتاريخ."},{"i":"lt-04","s":19,"h":"حدود المدرسة","t":"recall","x":"اشرح بجملتين فكرة النقد التاريخي والسيري ومثال عليها. . المدرسة ترى أن العمل الأدبي ينعكس فيه حياة المؤلف وعصره، فنفهمه بمعرفة السياق. مثال: قصيدة London لبليك لا تفهم جيدا إلا بمعرفة الفقر والظلم في إنجلترا في زمنه."},{"i":"lt-04","s":20,"h":"حدود المدرسة","t":"write","x":"على نمط امتحانات الكلية: اشرح النقد التاريخي والسيري مبرزا مبادئه وأهم نقد وجه له (من 5 إلى 6 جمل). . النقد التاريخي والسيري يرى الأدب انعكاسا لحياة المؤلف وعصره، ويقول إن العمل لا يفهم بمعزل عن السياق السياسي والاجتماعي. أوضح من صاغ مبادئه هيبوليت تين بفكرة race وmilieu وmoment. يسأل الناقد عن المؤلف والزمن والأحداث والمعتقدات ثم يستعين بها في فهم العمل، مثل ربط London لبليك بظلم المجتمع في إنجلترا. ينتقد البعض هذه المدرسة لأنها قد تحول الدراسة الأدبية إلى سيرة وتاريخ وتهمل جماليات النص."},{"i":"lt-05","s":1,"h":"مقدمة","t":"learn","x":"نطبق النقد التاريخي النهاردة هنقرأ قصيدة Ozymandias بنضارة النقد التاريخي. هنسأل: مين الكاتب؟ إمتى اتكتبت؟ إيه اللي حصل في الزمن ده؟ القصيدة سونيتة sonnet يعني 14 سطر، كتبها Percy Bysshe Shelley ."},{"i":"lt-05","s":2,"h":"مقدمة","t":"learn","x":"نص القصيدة (مقتطف) I met a traveller from an antique land, / Who said: Two vast and trunkless legs of stone / Stand in the desert... Nothing beside remains. Round the decay / Of that colossal wreck, boundless and bare / The lone and level sands stretch far away."},{"i":"lt-05","s":4,"h":"السياق التاريخي","t":"learn","x":"مين هو أوزيماندياس؟ أوزيماندياس Ozymandias هو الاسم اليوناني للفرعون رمسيس الثاني Ramesses II . حكم مصر حوالي سنة 1279 إلى 1213 قبل الميلاد، وكان من أقوى حكام العالم القديم. بنى معابد وتماثيل ضخمة، ولقبوه برمسيس الأكبر. يعني ملك الملوك فعلا."},{"i":"lt-05","s":5,"h":"السياق التاريخي","t":"learn","x":"إيه اللي شجع شيلي يكتبها؟ في إنجلترا زمن شيلي كان فيه اهتمام كبير بمصر القديمة واكتشافاتها. ناس كتير بتقول إن اكتشاف تمثال ضخم لرمسيس ونقله للمتحف البريطاني كان في أذهان الناس وقتها. وكمان شيلي اتأثر بكتابات يونانية عن مصر، منها كتابات المؤرخ Diodorus Siculus اللي نقل نقشا على قاعدة تمثال لرمسيس."},{"i":"lt-05","s":6,"h":"السياق التاريخي","t":"learn","x":"الكتابة والنشر القصيدة نشرت لأول مرة في مجلة The Examiner في 11 يناير 1818. وكتبها شيلي في جو منافسة ودية مع صديقه Horace Smith اللي كتب قصيدة بنفس الموضوع. في الأول مكنتش مشهورة جدا، وبعدين بقت من أشهر قصايده."},{"i":"lt-05","s":7,"h":"السياق التاريخي","t":"mc","x":"أول نشر لقصيدة Ozymandias كان في: ؟ ديوان Rosalind and Helen سنة 1819 / مجلة The Examiner سنة 1818 / كتاب Diodorus / مسرحية لشكسبير . نشرت في مجلة The Examiner بتاريخ 11 يناير 1818."},{"i":"lt-05","s":9,"h":"قراءة القصيدة بعد معرفة السياق","t":"learn","x":"المعنى الأساسي القصيدة بتقول إن أي سلطة مؤقتة مهما كان صاحبها متكبر. التمثال محطم، والوجه نصف غارق في الرمال، والنقش بيقول: \" Look on my Works, ye Mighty, and despair! \" لكن مفيش حاجة باقية، الرمال بتمتد في كل مكان."},{"i":"lt-05","s":10,"h":"قراءة القصيدة بعد معرفة السياق","t":"learn","x":"علاقة بزمن شيلي شيلي عاش في زمن ملكيات وسلطات قوية في أوروبا. كتير من القراء بيشوفوا في القصيدة تحذيرا ضمنيا للحكام المستبدين إن سلطتهم هتروح. ده تفسير مقبول، بس مفيش حد بيقدر يقطع بنية الكاتب بشكل مؤكد."},{"i":"lt-05","s":11,"h":"قراءة القصيدة بعد معرفة السياق","t":"learn","x":"الفنان فاضل الحاجة الوحيدة اللي بقت هي مهارة النحات اللي قدر يصور مشاعر الملك. يعني الفن بيعيش أكتر من السلطة. وفي نفس الوقت قصيدة شيلي نفسها لسه بتتقرأ بعد أكتر من 200 سنة."},{"i":"lt-05","s":12,"h":"قراءة القصيدة بعد معرفة السياق","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ حسب القراءة التاريخية، شيلي كتب القصيدة بعد حكاية عن رمسيس الثاني المصري. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / حسب النقد الجديد، نية المؤلف هي المعيار الأفضل لتقييم العمل. . أوزيماندياس هو اسم رمسيس الثاني عند اليونان."},{"i":"lt-05","s":14,"h":"أخطاء شائعة وتصحيحها","t":"learn","x":"تصحيح مهم في بعض الكتب مكتوب إن القصيدة نشرت سنة 1819 في ديوان Rosalind and Helen. ده غير دقيق: التاريخ الصحيح للنشر الأول هو 11 يناير 1818 في The Examiner. ومكتوب كمان إن رمسيس \"ملك من القرن الثالث عشر\"، والصح إنه من القرن الثالث عشر قبل الميلاد، يعني قبل حوالي 3300 سنة."},{"i":"lt-05","s":15,"h":"أخطاء شائعة وتصحيحها","t":"mc","x":"متى حكم رمسيس الثاني تقريبا؟ ؟ القرن الثالث عشر بعد الميلاد / حوالي 1279 إلى 1213 قبل الميلاد / القرن الأول الميلادي / سنة 1818 . الفترة المقبولة لحكمه هي حوالي 1279 إلى 1213 ق.م."},{"i":"lt-05","s":16,"h":"أخطاء شائعة وتصحيحها","t":"learn","x":"الملخص القصيدة عن رمسيس الثاني (أوزيماندياس). نشرت 1818 في The Examiner. اتكتبت في جو اهتمام بمصر القديمة ومنافسة مع Horace Smith. الفكرة: السلطة مؤقتة والفن أبقى."},{"i":"lt-05","s":17,"h":"أخطاء شائعة وتصحيحها","t":"recall","x":"وضح كيف يساعدنا معرفة التاريخ على فهم Ozymandias. . معرفة أن Ozymandias هو رمسيس الثاني، وأن الاهتمام بمصر القديمة كان كبيرا في زمن شيلي، تساعدنا على فهم تمثال الملك المحطم كرمز لزوال السلطة مهما عظمت."},{"i":"lt-05","s":18,"h":"أخطاء شائعة وتصحيحها","t":"write","x":"على نمط امتحانات الكلية: طبق النقد التاريخي على قصيدة Ozymandias (من 5 إلى 6 جمل). . القصيدة تتناول الفرعون رمسيس الثاني المعروف عند اليونان بأوزيماندياس. نشرت في The Examiner سنة 1818 في زمن اهتمام الإنجليز بمصر القديمة وآثارها. استفاد شيلي من الروايات القديمة عن النقوش، وكتب القصيدة في مسابقة ودية مع Horace Smith. تقرأ القصيدة تاريخيا على أنها تعبير عن أن السلطة مؤقتة وأن الفن والكلمة أبقى، وقد يرى بعض القراء فيها تحذيرا للحكام المستبدين في زمنه."},{"i":"lt-06","s":1,"h":"مقدمة","t":"learn","x":"هاملت وزمنه مسرحية Hamlet لشكسبير من أشهر المسرحيات في العالم. النهاردة هنسأل: إيه اللي لازم نعرفه عن إنجلترا الإليزابيثية علشان نفهمها؟ وفي النقد التاريخي نسأل أسئلة زي: ليه هاملت ميبقاش ملك بعد موت أبوه؟"},{"i":"lt-06","s":3,"h":"هاملت وحياة الكاتب وعصره","t":"learn","x":"هل المسرحية بتعكس شخصيات حقيقية؟ بعض النقاد قالوا إن في المسرحية إشارات لشخصيات من عصر شكسبير. مثلا بعضهم ربط وصف أوفيليا لهاملت بالإيرل إسكس Earl of Essex ، المفضل عند الملكة إليزابيث قبل ما يتعدم بتهمة الخيانة سنة 1601. وبعضهم ربط بولونيوس Polonius بالوزير بيرلي Burghley ، اللي كان معروف بنصائحه الكتيرة. دي كلها تفسيرات محتملة، مفيش حد يقدر يجزم بيها."},{"i":"lt-06","s":4,"h":"هاملت وحياة الكاتب وعصره","t":"learn","x":"إسكس وبيرلي: حذر مطلوب أهم نقطة في النقد التاريخي إننا نفرق بين الدليل والتخمين. التشابه بين شخصية وشخص حقيقي ممكن يكون صدفة. علشان كده بنكتب: some critics suggest مش \"الأكيد إن\"."},{"i":"lt-06","s":5,"h":"هاملت وحياة الكاتب وعصره","t":"mc","x":"أنسب صياغة لعلاقة بولونيوس ببيرلي؟ ؟ بولونيوس هو بيرلي بالتأكيد / بعض النقاد يرون شبها بين بولونيوس وبيرلي / مفيش أي شبه ممكن / شكسبير كتب عن بيرلي فقط . في الأمر اجتهاد، فنصيغه بعبارة حذرة."},{"i":"lt-06","s":7,"h":"السؤال التاريخي: ليه هاملت مش ملك؟","t":"learn","x":"عرش الدنمارك في المسرحية هاملت هو ابن الملك الوحيد، ومع ذلك مجاش الحكم له بعد موت أبوه. بعض الدارسين بيفسروا ده بإن عرش الدنمارك في القصة كان بالانتخاب مش بالوراثة المباشرة. يعني مجلس النبلاء هو اللي بيختار الملك. وبالتالي كلوديوس قدر ياخد الحكم قبل هاملت."},{"i":"lt-06","s":8,"h":"السؤال التاريخي: ليه هاملت مش ملك؟","t":"learn","x":"كلوديوس مغتصب العرش الناقد J. Dover Wilson قال إن جمهور شكسبير كان بيشوف هاملت الوريث الشرعي وكلوديوس مغتصبا للعرش. وده من أهم العوامل في المسرحية. وهاملت نفسه بيوصف كلوديوس بإنه لص سرق التاج: A cutpurse of the empire and the rule ."},{"i":"lt-06","s":9,"h":"السؤال التاريخي: ليه هاملت مش ملك؟","t":"learn","x":"هاملت كان ينتظر الانتخاب في آخر المسرحية بيقول هاملت إن كلوديوس تدخل Popped in between th' election and my hopes أي بين الانتخاب وآماله. ده بيوحي إنه كان متوقع يتم اختياره. وده بيفسر جزء من غضبه."},{"i":"lt-06","s":10,"h":"السؤال التاريخي: ليه هاملت مش ملك؟","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ النقد الجديد والتاريخانية الجديدة متفقان على قراءة النص بمعزل عن التاريخ. / الدراسات الأدبية في التعددية الثقافية تتفق على إجابة واحدة لمن يقرر أي ثقافات تدخل المنهج. / حسب هذه القراءة، فكرة الانتخاب تساعد على تفسير أن هاملت ما أخدش العرش بعد موت أبيه. / حسب النقد الجديد، نية المؤلف هي المعيار الأفضل لتقييم العمل. . الانتخاب هو تفسير تاريخي مقترح لسؤال الوراثة."},{"i":"lt-06","s":12,"h":"تقاليد الانتقام","t":"learn","x":"مسرحية انتقام revenge tragedy الجمهور الإليزابيثي كان يعرف نمط معين: جريمة، ثم روح أو شخص يطلب الانتقام، ثم عقبات، وفي الآخر موت الجاني والمنتقم وغالبا كل الأبطال. شكسبير ماشي على النمط ده في هاملت، والجمهور كان بيتوقعه."},{"i":"lt-06","s":13,"h":"تقاليد الانتقام","t":"learn","x":"التوبة والصلاة في عصر شكسبير كان الناس بيعتقدوا إن التوبة لازم تكون بالكلام علشان تتقبل. لما لايرتس بيقول إنه عايز يقتل هاملت في الكنيسة، هو فعلا عايز يهلك روحه وجسمه. وده بيفسر ليه الجمهور كان بيحس بقسوة الجملة دي."},{"i":"lt-06","s":14,"h":"تقاليد الانتقام","t":"mc","x":"أي عنصر من العناصر دي نمط مسرحية الانتقام الإليزابيثية؟ ؟ بداية بجريمة ثم طلب انتقام ثم عقبات / قصة حب بسيطة بنهاية سعيدة فقط / وصف طبيعة فقط / مناقشة اقتصادية . نمط الانتقام: جريمة، طلب انتقام، عقبات، موت أطراف عدة."},{"i":"lt-06","s":15,"h":"تقاليد الانتقام","t":"learn","x":"تصحيح وحذر ورد في بعض الكتب إن الأحداث في \"القرن الحادي عشر\" الدنماركي. القصة الأصلية مرتبطة بأسطورة دنماركية قديمة، لكن المسرحية نفسها مش مبنية على فترة تاريخية مضبوطة. فالأحسن نتكلم عن عصر شكسبير وجمهوره بدل ما نحدد قرن معين للأحداث."},{"i":"lt-06","s":16,"h":"تقاليد الانتقام","t":"learn","x":"الملخص الناقد التاريخي يسأل عن الأشخاص، العرش، وتقاليد الانتقام. أمثلة: إسكس وبولونيوس (اجتهاد)، عرش انتخابي (تفسير)، مسرحية الانتقام (نمط). والمهم: نفرق بين الدليل والتخمين."},{"i":"lt-06","s":17,"h":"تقاليد الانتقام","t":"recall","x":"اذكر سؤالين يطرحهما الناقد التاريخي على Hamlet. . لماذا لم يرث هاملت العرش؟ وما تقاليد مسرحية الانتقام في عصر شكسبير التي كان يعرفها جمهوره؟"},{"i":"lt-06","s":18,"h":"تقاليد الانتقام","t":"write","x":"على نمط امتحانات الكلية: كيف يفسر النقد التاريخي مسرحية Hamlet؟ (من 5 إلى 6 جمل). . يقرأ النقد التاريخي Hamlet في ضوء عصر شكسبير. يرى بعض النقاد إشارات إلى شخصيات من العصر مثل الإيرل إسكس وبيرلي، لكنها تبقى تفسيرات محتملة. ويسأل الناقد لماذا لم يرث هاملت العرش، فيقترح بعض الدارسين أن عرش الدنمارك في المسرحية كان انتخابيا، وأن كلوديوس يعد مغتصبا للعرش بحسب J. Dover Wilson. كما يربط المسرحية بتقاليد مسرحية الانتقام التي كان الجمهور يعرفها، مثل الجريمة وطلب الانتقام والعقبات."},{"i":"lt-07","s":1,"h":"مقدمة","t":"learn","x":"التاريخ برضه نص تخيل إنك بتقرا خبر قديم في جريدة، وبعدين بتقرا قصيدة من نفس الأسبوع. ممكن الاتنين يحكوا نفس الأفكار عن الملك والناس والسلطة. ده بالظبط اللي بتعمله التاريخانية الجديدة New Historicism ."},{"i":"lt-07","s":3,"h":"البداية","t":"learn","x":"إمتى ومين؟ ظهرت التاريخانية الجديدة في الجامعات الأمريكية في الثمانينات. بدايتها المعروفة مع Stephen Greenblatt وكتابه Renaissance Self-Fashioning سنة 1980. وجرينبلات هو اللي استخدم المصطلح في مقدمة عدد خاص من مجلة Genre سنة 1982."},{"i":"lt-07","s":4,"h":"البداية","t":"learn","x":"رد فعل على إيه؟ التاريخانية الجديدة ظهرت كرد فعل على النقد الجديد (New Criticism) اللي كان بيدرس النص بعيدا عن التاريخ. وكمان اختلفت مع النقد التاريخي القديم، لأنها مش بتتعامل مع التاريخ كخلفية ثابتة."},{"i":"lt-07","s":5,"h":"البداية","t":"mc","x":"بدأت التاريخانية الجديدة بكتاب: ؟ Practical Criticism / Renaissance Self-Fashioning / Poetics / The Second Sex . كتاب جرينبلات سنة 1980 هو نقطة الانطلاق المعروفة."},{"i":"lt-07","s":7,"h":"الأفكار الأساسية","t":"learn","x":"النص جزء من الثقافة الأدب مش منفصل عن التاريخ. هو جزء من a system of signs that constitutes a culture أي نظام علامات بيكون ثقافة. والعمل بيقول لنا حاجة عن أفكار وسلطة زمنه. فالسياق مش خلفية، السياق جزء من النص."},{"i":"lt-07","s":8,"h":"الأفكار الأساسية","t":"learn","x":"التاريخ نفسه تفسير التاريخانية الجديدة بتقول إن التاريخ مش مجرد وقائع موضوعية. المؤرخ نفسه ابن عصره، وبيفسر حسب موازين القوة. عبارتين مشهورتين: historicity of texts أي النص له تاريخ، و textuality of history أي التاريخ نفسه بيتحكي كنص."},{"i":"lt-07","s":9,"h":"الأفكار الأساسية","t":"learn","x":"مفيش فرق بين نص أدبي وغير أدبي الناقد يقرا رسائل ومذكرات ولوحات ووثائق طبية زي ما يقرا القصيدة. كلها cultural artifacts منتجات ثقافية. والتاريخانيين الجدد بيدوروا على surprising coincidences أي تلاقيات مفاجئة بين نص أدبي ووثيقة من نفس العصر."},{"i":"lt-07","s":10,"h":"الأفكار الأساسية","t":"learn","x":"الشعرية الثقافية جرينبلات في كتابه Shakespearean Negotiations (1988) تكلم عن poetics of culture : شبكة من التبادلات و negotiation أي التفاوض بتخلي المجتمع يوفق بين أفكار متناقضة. ولاحظ إن المصطلحات دي مأخوذة من السوق: تبادل وتفاوض وتداول."},{"i":"lt-07","s":11,"h":"الأفكار الأساسية","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. / الأنا (ego) هو الجزء الذي يوازن بين الهو والأنا الأعلى. / التاريخانية الجديدة بتفرق بشكل حاد بين النص الأدبي والنص غير الأدبي. / النقد الجديد يفصل النص، والتاريخانية الجديدة تربطه بالثقافة. . هي بترفض الفصل وبتعتبر الاتنين منتجات ثقافية."},{"i":"lt-07","s":13,"h":"تأثيرات وانتقادات","t":"learn","x":"من أثر فيها؟ جرينبلات ذكر من المؤثرين عليه ميشيل فوكو Michel Foucault وفريدريك جيمسون Fredric Jameson وجان فرانسوا ليوتار Jean-François Lyotard . وفوكو بالذات أثر بأفكاره عن علاقة المعرفة بالسلطة."},{"i":"lt-07","s":14,"h":"تأثيرات وانتقادات","t":"learn","x":"مثال: Heart of Darkness في دراسات تاريخانية جديدة على روايات جوزيف كونراد، زي Heart of Darkness ، بيقرأوا الرواية بجانب كتابات الرحلات والاستعمار في نفس الفترة علشان يشوفوا كيف تعمل السلطة في النص. فالاستعمار مش معلومة في الخلفية، هو جزء من الطريقة اللي الرواية بتتكلم بيها."},{"i":"lt-07","s":15,"h":"تأثيرات وانتقادات","t":"learn","x":"الانتقادات بعض النقاد قالوا إن التاريخانيين الجدد بيعتدوا على مجال المؤرخين والاقتصاديين. وناقد زي إدوارد بيشتر قلق من تسييس الدراسات الأدبية. وناس تانية بتقول إن المنهج غامض وصعب تحديده، لأنه بيجمع تخصصات كتير."},{"i":"lt-07","s":16,"h":"تأثيرات وانتقادات","t":"mc","x":"أي عبارة تعبر عن التاريخانية الجديدة؟ ؟ النص يقرأ لوحده وبعيد عن التاريخ / النص والتاريخ يشكلان بعضهما / القارئ هو المعنى الوحيد / اللغة بلا معنى أبدا . التاريخانية الجديدة ترى النص والتاريخ متفاعلين."},{"i":"lt-07","s":17,"h":"تأثيرات وانتقادات","t":"learn","x":"الفرق عن النقد التاريخي القديم النقد التاريخي القديم: التاريخ خلفية ثابتة تفسر النص. التاريخانية الجديدة: النص والتاريخ يصنعان بعض، والتاريخ نفسه مفتوح للتفسير. وفيه فرق في التركيز: القديم بيركز على المؤلف وحياته، والجديد على الثقافة والسلطة."},{"i":"lt-07","s":18,"h":"تأثيرات وانتقادات","t":"learn","x":"الملخص نشأت أمريكا الثمانينات مع جرينبلات (1980). النص جزء من الثقافة. التاريخ نفسه تفسير. مفيش فرق بين أدبي وغير أدبي. مفاتيح: culture وpower وnegotiation."},{"i":"lt-07","s":19,"h":"تأثيرات وانتقادات","t":"recall","x":"اذكر اثنين من الفروق بين النقد التاريخي القديم والتاريخانية الجديدة. . القديم يرى التاريخ خلفية ثابتة، والجديد يرى النص والتاريخ يشكلان بعضهما. القديم يركز على المؤلف، والجديد على الثقافة والسلطة ولا يفرق بين نص أدبي وغير أدبي."},{"i":"lt-07","s":20,"h":"تأثيرات وانتقادات","t":"write","x":"على نمط امتحانات الكلية: اشرح مبادئ التاريخانية الجديدة (من 5 إلى 6 جمل). . التاريخانية الجديدة حركة نقدية ظهرت في الجامعات الأمريكية في الثمانينات مع ستيفن جرينبلات وكتابه Renaissance Self-Fashioning (1980). ترى أن الأدب جزء من ثقافة عصره وليس منفصلا عنها، وأن التاريخ نفسه تفسير يتأثر بالسلطة. لا تفرق بين النص الأدبي وغير الأدبي، وتقرأ الاثنين كمنتجات ثقافية. اهتمت بمفاهيم التبادل والتفاوض والسلطة، وتأثرت بفوكو. ظهرت كرد فعل على النقد الجديد الذي فصل النص عن التاريخ."},{"i":"lt-08","s":1,"h":"مقدمة","t":"learn","x":"فكرة جديدة لو سألتك: إيه الفرق بين جملة في قصيدة وجملة في إعلان؟ هتقول: القصيدة ليها طريقة خاصة في استخدام اللغة. ودي بالظبط فكرة الشكلانية Formalism . الشكلانية تشوف الأدب استخدام متخصص للغة، وبتدرسه من داخله."},{"i":"lt-08","s":3,"h":"الأصل الروسي","t":"learn","x":"البداية في روسيا الشكلانية الروسية Russian Formalism بدأت في روسيا في العقد الثاني من القرن العشرين. نادي موسكو اللغوي Moscow Linguistic Circle اتأسس سنة 1915، وجماعة أبوياز OPOYAZ في بتروغراد حوالي 1916. من أبرز روادها: فيكتور شكلوفسكي Viktor Shklovsky ورومان ياكوبسون Roman Jakobson وبوريس إيخنباوم Boris Eikhenbaum ."},{"i":"lt-08","s":4,"h":"الأصل الروسي","t":"learn","x":"هدفهم رفضوا النقد غير المنظم اللي كان سائد، وحاولوا يبنوا literary science أي علم للأدب بيدرس اللغة الشعرية نفسها. يعني بدل ما نسأل عن حياة الشاعر، نسأل: إزاي اتصنع النص؟"},{"i":"lt-08","s":5,"h":"الأصل الروسي","t":"mc","x":"هدف الشكلانية الروسية كان: ؟ دراسة حياة الكتاب / بناء علم للأدب يدرس اللغة الشعرية / تحليل أحلام الشعراء / دراسة الاقتصاد فقط . أرادوا علما للأدب يدرس اللغة الأدبية نفسها."},{"i":"lt-08","s":7,"h":"الأدب لغة خاصة","t":"learn","x":"الأدب ضد اللغة العادية الشكلانيين شافوا فرق أساسي بين اللغة الأدبية واللغة العملية. اللغة العملية بتنقل معلومة: \"افتح الباب\". اللغة الأدبية بتلفت النظر لشكلها هي نفسها. وبتدي القارئ تجربة خاصة، مش بس معلومة."},{"i":"lt-08","s":8,"h":"الأدب لغة خاصة","t":"learn","x":"الأدبية Literariness السمات اللي بتميز النص الأدبي اسمها الأدبية literariness . هدف الناقد إنه يكتشف الوسائل devices اللي بتصنع الأدبية. زي الاستعارة والإيقاع والقافية والصورة والتكرار."},{"i":"lt-08","s":9,"h":"الأدب لغة خاصة","t":"learn","x":"الغرابة defamiliarization شكلوفسكي قال إن الفن بيخلينا نشوف الحاجات المألوفة كأنها جديدة. اللغة الشعرية بتكسر العادة وتخلي القارئ يتوقف ويتأمل. مثال: بدل \"الشمس طلعت\" نقول \"الصبح فتح عينه الذهبية\"."},{"i":"lt-08","s":10,"h":"الأدب لغة خاصة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. / الشكلانيون يرون أن وظيفة اللغة الأدبية هي مجرد نقل معلومات. / أنهي جملة من دول صحيحة؟ . وظيفتها تقديم تجربة خاصة تلفت النظر لشكل اللغة نفسها."},{"i":"lt-08","s":12,"h":"ريتشاردز وإليوت","t":"learn","x":"إنجلترا: ريتشاردز في إنجلترا ظهرت حركة مشابهة مع آي. إيه. ريتشاردز I. A. Richards وكتابه Practical Criticism (1929). أعطى الطلبة قصايد من غير أسماء شعرائها علشان يقروا النص لوحده. النتيجة: اكتشف إن الطلبة كتير بيحكموا بسمعة الشاعر مش بالنص."},{"i":"lt-08","s":13,"h":"ريتشاردز وإليوت","t":"learn","x":"إليوت T. S. Eliot في مقال Tradition and the Individual Talent (1919) قال إن الشعر مش تعبير عن الشخصية بل هروب منها: Poetry is not a turning loose of emotion, but an escape from emotion . وأطلق في مقاله عن هاملت (1919) مصطلح objective correlative أي المعادل الموضوعي: أشياء وأحداث بتثير عاطفة محددة."},{"i":"lt-08","s":14,"h":"ريتشاردز وإليوت","t":"mc","x":"مصطلح objective correlative مرتبط ب: ؟ دريدا / إليوت / فرويد / سوسير . إليوت استخدمه في مقاله عن هاملت."},{"i":"lt-08","s":15,"h":"ريتشاردز وإليوت","t":"learn","x":"القراءة المتأنية close reading الشكلاني يقرا بتأن: كلمات ومعانيها الحرفية والإيحائية، وبعدين الأنماط والعلاقات بين الأجزاء، حتى بين المقاطع في القصيدة أو الفصول في الرواية. وبيشوف إن الشكل مش مجرد شكل جملة بل علاقة الأجزاء ببعض."},{"i":"lt-08","s":16,"h":"ريتشاردز وإليوت","t":"learn","x":"الملخص الشكلانية الروسية 1915-1916، شكلوفسكي وياكوبسون. أدبية، غرابة، وسائل. ريتشاردز 1929. إليوت 1919: impersonality وobjective correlative. وكل ده بيمهد للنقد الجديد الأمريكي."},{"i":"lt-08","s":17,"h":"ريتشاردز وإليوت","t":"recall","x":"ما المقصود ب literariness؟ وكيف يختلف الأدب عن اللغة العادية عند الشكلانيين؟ . الأدبية هي السمات التي تجعل النص أدبيا. اللغة العادية تنقل معلومة، أما الأدب فيلفت الانتباه إلى شكله اللغوي ويقدم تجربة خاصة."},{"i":"lt-08","s":18,"h":"ريتشاردز وإليوت","t":"write","x":"على نمط امتحانات الكلية: اشرح الشكلانية وأهم مبادئها (من 5 إلى 6 جمل). . الشكلانية ترى أن العمل الأدبي كيان مستقل يفهم من خلال سماته الداخلية لا حياة المؤلف ولا التاريخ. بدأت في روسيا مع نادي موسكو اللغوي سنة 1915 ورواد مثل شكلوفسكي وياكوبسون، وحاولت بناء علم للأدب. ترى أن اللغة الأدبية تختلف عن اللغة العملية وتتميز بالأدبية. وفي إنجلترا مثلها ريتشاردز وإليوت، ويعتمد المنهج على القراءة المتأنية للنص."},{"i":"lt-09","s":1,"h":"مقدمة","t":"learn","x":"النص يكفي تخيل إنك لقيت ورقة فيها قصيدة من غير اسم ولا تاريخ. هل تقدر تفهمها؟ النقد الجديد New Criticism بيقول: أيوه، النص فيه كل اللي محتاجه. وده بيخلينا نركز على الكلمات والصور والبنية."},{"i":"lt-09","s":3,"h":"النشأة","t":"learn","x":"أمريكا والنقد الجديد نقاد أمريكان زي John Crowe Ransom و Robert Penn Warren و Cleanth Brooks طوروا الشكلانية وسموها النقد الجديد. الاسم جه من كتاب رانسوم The New Criticism سنة 1941. ركزوا على اللغة والشكل والبنية، وشافوا العمل الأدبي موضوعا جماليا مستقلا."},{"i":"lt-09","s":4,"h":"النشأة","t":"learn","x":"الوحدة العضوية organic unity النقاد الجدد قالوا إن الشكل والمعنى مش بيتفصلوا. زي جسم الإنسان: مينفعش نفصل شكله عن وظيفته. فالقراءة الجيدة بتكتشف إزاي كل جزء بيخدم الكل."},{"i":"lt-09","s":5,"h":"النشأة","t":"mc","x":"اسم النقد الجديد مأخوذ من: ؟ مقال لإليوت / كتاب رانسوم The New Criticism (1941) / كتاب لفرويد / مسرحية لشكسبير . رانسوم نشر كتابا بهذا الاسم سنة 1941."},{"i":"lt-09","s":7,"h":"المصطلحات الأساسية","t":"learn","x":"المغالطة القصدية Intentional Fallacy في مقال (1946) ل Wimsatt و Beardsley قالوا: نية المؤلف مش متاحة ومش مطلوبة كمعيار لنجاح العمل. يعني ميصحش نحكم على قصيدة بسؤال: \"قصد الشاعر إيه؟\" بل بما هو مكتوب."},{"i":"lt-09","s":8,"h":"المصطلحات الأساسية","t":"learn","x":"المغالطة الوجدانية Affective Fallacy في مقال تاني (1949) قالوا: ميصحش نحدد قيمة العمل بتأثيره على القارئ. يعني \"القصيدة دي بكتني\" مش دليل على إنها جيدة."},{"i":"lt-09","s":9,"h":"المصطلحات الأساسية","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ النقد التاريخي بيشترط معرفة السياق التاريخي والاجتماعي. / النقد الجديد يفصل النص، والتاريخانية الجديدة تربطه بالثقافة. / حسب النقد الجديد، نية المؤلف هي المعيار الأفضل لتقييم العمل. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. . المغالطة القصدية بتقول إن النية مش متاحة ومش مطلوبة كمعيار."},{"i":"lt-09","s":10,"h":"المصطلحات الأساسية","t":"learn","x":"المعادل الموضوعي والملمس texture المعادل الموضوعي لإليوت: مجموعة أشياء أو مواقف تثير عاطفة معينة مباشرة. والملمس texture هو اتساق الصور في القصيدة: صورة مسيطرة أو أنماط من صور مرتبطة، وكان مؤشرا لجودة القصيدة عند بعضهم."},{"i":"lt-09","s":11,"h":"المصطلحات الأساسية","t":"learn","x":"التوتر tension والمفارقة irony و paradox التوتر هو الوحدة اللي بتنتج من حل التضادات، وغالبا بالمفارقة أو التناقض الظاهري. التناقض الظاهري paradox جملة فيها تناقض في الشكل لكن ليها معنى أعمق. زي \"مفيش أصعب من السهل\"."},{"i":"lt-09","s":12,"h":"المصطلحات الأساسية","t":"learn","x":"الغموض ambiguity الغموض هو لما كلمة أو صورة تقدر معنيين أو أكتر. في الأدب الغموض مصدر ثراء مش عيب. مثال: صورة الشجرة ممكن تعبر عن الصمود لأنها تعيش مئات السنين، وعن التجدد لأنها بتتجدد كل ربيع."},{"i":"lt-09","s":13,"h":"المصطلحات الأساسية","t":"mc","x":"أي مثال يوضح الغموض (ambiguity) الأدبي؟ ؟ كلمة لها معنى واحد فقط / صورة تقدر تعني الصمود والتجدد معا / رقم هاتف / تاريخ ميلاد الشاعر . الغموض هو تعدد المعنى، وفي الأدب بيضيف عمقا."},{"i":"lt-09","s":14,"h":"المصطلحات الأساسية","t":"learn","x":"الرمز symbol لما صورة تاخد معنى أكبر من حقيقتها بتبقى رمز. وهنا مأزق: الرمز بيفتح على العالم برا النص، رغم إن النقاد الجدد بيعتبروا النص مغلق. وده نقد وجهوه للمدرسة."},{"i":"lt-09","s":15,"h":"المصطلحات الأساسية","t":"learn","x":"نقد المدرسة النقاد بيقولوا إن النقد الجديد بيهمل التاريخ والمؤلف والقارئ، وإنه أحيانا بيدعي إن المعنى يعرف بشكل موضوعي تماما. ومن هنا جت استجابة القارئ والتاريخانية الجديدة."},{"i":"lt-09","s":16,"h":"المصطلحات الأساسية","t":"learn","x":"الملخص النقد الجديد: رانسوم 1941، بروكس وورين. وحدة عضوية. مغالطة قصدية (1946) ووجدانية (1949). توتر ومفارقة وغموض ورمز. النص وحده، والقراءة المتأنية."},{"i":"lt-09","s":17,"h":"المصطلحات الأساسية","t":"recall","x":"فرق بين المغالطة القصدية والمغالطة الوجدانية. . القصدية: الحكم على العمل بنية المؤلف. الوجدانية: الحكم عليه بتأثيره على القارئ. وكلاهما يبعدنا عن النص نفسه."},{"i":"lt-09","s":18,"h":"المصطلحات الأساسية","t":"write","x":"على نمط امتحانات الكلية: اشرح مبادئ النقد الجديد ومصطلحاته (من 5 إلى 6 جمل). . النقد الجديد حركة أمريكية طورت الشكلانية، مع رانسوم وبروكس وورين، وسميت من كتاب رانسوم 1941. يرى النص كيانا جماليا مستقلا ويقرأه قراءة متأنية. يرفض المغالطة القصدية أي الحكم بنية المؤلف، والمغالطة الوجدانية أي الحكم بتأثير النص على القارئ. من مصطلحاته المعادل الموضوعي والملمس والتوتر والمفارقة والغموض. ويرى أن الشكل والمعنى وحدة عضوية."},{"i":"lt-10","s":1,"h":"مقدمة","t":"learn","x":"صندوق العدة القراءة المتأنية محتاجة أدوات، زي الميكانيكي. النهاردة هنتعرف على أهم الأدوات الأدبية اللي هنستخدمها في تحليل أي قصيدة. كل أداة هنشرحها بمثال بسيط."},{"i":"lt-10","s":3,"h":"أدوات الصوت","t":"learn","x":"الجناس الاستهلالي Alliteration هو تكرار صوت الحرف الأول في كلمات متقاربة. مثال من Ozymandias: cold command و boundless and bare . بيدي إيقاع ممتع، وبيلفت الانتباه."},{"i":"lt-10","s":4,"h":"أدوات الصوت","t":"learn","x":"التجانس الصوتي Assonance هو تكرار صوت حرف العلة في كلمات متقاربة. في السطر Half sunk a shattered visage lies تتكرر حرف الألف القصيرة في half وshattered. الفرق: alliteration في أول الكلمة، assonance في صوت العلة."},{"i":"lt-10","s":5,"h":"أدوات الصوت","t":"mc","x":"cold command مثال على: ؟ alliteration / assonance / personification / apostrophe . تكرار حرف c في أول الكلمتين هو alliteration."},{"i":"lt-10","s":7,"h":"أدوات الشكل","t":"learn","x":"السونيتة Sonnet والوزن السونيتة 14 سطرا. وغالبا بالوزن الإيامبي الخماسي iambic pentameter : خمس مقاطع، كل مقطع نبرة خفيفة ثم قوية، زي دق القلب: da-DUM. الوزن ده قريب من إيقاع الكلام الطبيعي، لكنه منظم كفاية علشان يتميز عنه."},{"i":"lt-10","s":8,"h":"أدوات الشكل","t":"learn","x":"القافية Rhyme scheme القافية هي نمط تكرار نهايات الأسطر. نرمز لها بحروف. قافية Ozymandias غير تقليدية، وبتبدأ بنمط ABABACDCEDEFEF. كتير من النقاد بيقولوا إن تغيير النمط في النص بيعكس تغير الزمن وانهيار النظام، وده تفسير مش حقيقة قاطعة."},{"i":"lt-10","s":9,"h":"أدوات الشكل","t":"learn","x":"التضمين Enjambment هو لما الجملة ما تخلصش في نهاية السطر وتكمل في اللي بعده. زي: Who said: Two vast and trunkless legs of stone / Stand in the desert . وده بيعمل توتر ويخلي القارئ يكمل علشان يعرف الباقي."},{"i":"lt-10","s":10,"h":"أدوات الشكل","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ التضمين (enjambment) موجود في القصيدة ويخلق توترا. / التضمين (enjambment) معناه إن السطر ينتهي بنقطة دايما. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. / استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. . التضمين هو استمرار المعنى للسطر التالي بدون وقف."},{"i":"lt-10","s":12,"h":"أدوات المعنى","t":"learn","x":"الاستعارة Metaphor استعارة معناها نقول إن شيء هو شيء تاني بدون أداة تشبيه. تمثال Ozymandias المحطم استعارة للسلطة وتاريخها وقدرة الزمن على تدميرها. أما التشبيه simile فبيستخدم like أو as."},{"i":"lt-10","s":13,"h":"أدوات المعنى","t":"learn","x":"التشخيص Personification هو إعطاء صفات بشرية لشيء غير حي. wrinkled lip, and sneer of cold command بيوصف وجه التمثال كأنه إنسان حي. وده بيخلينا نشوف الملك فعلا كشخص."},{"i":"lt-10","s":14,"h":"أدوات المعنى","t":"learn","x":"المخاطبة Apostrophe هي مخاطبة شخص غائب أو شيء غير حاضر. النقش في القصيدة بيخاطب كل \"العظماء\": Look on my Works, ye Mighty, and despair! الكلام موجه لأي حد يعدي على التمثال."},{"i":"lt-10","s":15,"h":"أدوات المعنى","t":"learn","x":"الصورة Imagery هي كل وصف يخاطب الحواس. في القصيدة: ساقين ضخمتين بلا جذع، وجه محطم نصفه غارق، صحراء ممتدة. كلها صور بصرية. وبتساعدنا نتخيل المشهد."},{"i":"lt-10","s":16,"h":"أدوات المعنى","t":"learn","x":"المفارقة Irony هي إن المعنى الحقيقي عكس الظاهر. تخيل: ملك بيكتب \"ابصروا أعمالي وانهاروا\" وكل اللي فاضل منه تمثال مكسور. التناقض بين كبريائه وزواله هو أساس المفارقة."},{"i":"lt-10","s":17,"h":"أدوات المعنى","t":"mc","x":"أي أداة أدبية وراء قصد أن \"تمثال محطم يمثل السلطة\"؟ ؟ alliteration / metaphor / rhyme / enjambment . المعنى الرمزي للتمثال استعارة للسلطة."},{"i":"lt-10","s":18,"h":"أدوات المعنى","t":"learn","x":"الملخص أدوات الصوت: alliteration وassonance. الشكل: sonnet وiambic pentameter وrhyme وenjambment. المعنى: metaphor وpersonification وapostrophe وimagery وirony. هتستخدمهم في الدرس الجاي."},{"i":"lt-10","s":19,"h":"أدوات المعنى","t":"recall","x":"فرق بين alliteration وassonance بمثال. . alliteration تكرار حرف البداية مثل cold command. assonance تكرار صوت العلة مثل half وshattered."},{"i":"lt-10","s":20,"h":"أدوات المعنى","t":"write","x":"على نمط امتحانات الكلية: اذكر ثلاث أدوات أدبية مع مثال لكل منها من أي قصيدة (من 4 إلى 5 جمل). . من الأدوات الأدبية الاستعارة، وهي كون تمثال Ozymandias المحطم رمزا للسلطة. ومنها alliteration مثل cold command. ومنها irony وهي التناقض بين نقش الملك المتكبر وحال التمثال المحطم. وهناك enjambment حين تمتد الجملة عبر السطور."},{"i":"lt-11","s":1,"h":"مقدمة","t":"learn","x":"قراءة بدون خلفية النهاردة هنقرا Ozymandias بعيون النقد الشكلي. مش هنسأل عن شيلي ولا مصر. هنسأل بس: إيه اللي في النص؟ وهنستخدم الأدوات اللي اتعلمناها في الدرس اللي فات."},{"i":"lt-11","s":2,"h":"مقدمة","t":"learn","x":"النص I met a traveller from an antique land, / Who said: Two vast and trunkless legs of stone / Stand in the desert. Near them, on the sand, / Half sunk, a shattered visage lies... My name is Ozymandias, King of Kings; / Look on my Works, ye Mighty, and despair! / Nothing beside remains."},{"i":"lt-11","s":4,"h":"الخطوة 1: الشكل","t":"learn","x":"السونيتة والوزن القصيدة سونيتة: 14 سطر بالوزن الإيامبي الخماسي. الوزن ده بيدي الكلام نبرة قريبة من الكلام الطبيعي لكن منظمة. وفي نفس الوقت نمط القافية غير تقليدي، فكأن القصيدة بتكسر النظام زي ما الزمن كسر التمثال."},{"i":"lt-11","s":5,"h":"الخطوة 1: الشكل","t":"learn","x":"الإطار القصيدة مروية على ثلاث طبقات: راوي بيحكي، وبيحكي عن مسافر، والمسافر بيحكي عن نقش. وده بيبعد القارئ عن الحدث كأنه صدى بعيد. وكل طبقة بتضيف مسافة زمنية."},{"i":"lt-11","s":6,"h":"الخطوة 1: الشكل","t":"mc","x":"التركيب الراوي ← المسافر ← النقش بيعمل: ؟ قرب مباشر من الملك / مسافة زمنية وتعدد طبقات في الحكي / مفيش أثر / حذف المعنى . الإطار بيجعل القصة تصل من بعيد وعبر وسطاء."},{"i":"lt-11","s":8,"h":"الخطوة 2: الصور واللغة","t":"learn","x":"الصورة Two vast and trunkless legs of stone : ساقين من حجر بلا جذع. كلمة trunkless تعني بدون جذع، يعني ناقص، ومحطم. والعبارة بتوحي بحجم هائل لكن مفكك. الصور البصرية كلها: ساقين، وجه نصف غارق، صحراء. بتدي إحساس بالدمار."},{"i":"lt-11","s":9,"h":"الخطوة 2: الصور واللغة","t":"learn","x":"التشخيص والمفارقة wrinkled lip, and sneer of cold command : كأن التمثال إنسان حي بيتكبر. والنحات قرأ شهواته جيدا: those passions read . المفارقة: كبرياء الملك مرسوم بدقة في تمثال مكسور."},{"i":"lt-11","s":10,"h":"الخطوة 2: الصور واللغة","t":"learn","x":"الأصوات cold command و boundless and bare جناس استهلالي، بيدي إحساس بالجمود والفراغ. وتكرار صوت الألف في half و shattered بيعمل تأثير تجانس صوتي. وكلمات كتير صوتها بيقترب من صوت التحطم."},{"i":"lt-11","s":11,"h":"الخطوة 2: الصور واللغة","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / التضمين (enjambment) موجود في القصيدة ويخلق توترا. . الجملة تمتد عبر الأسطر وتجعل القارئ يواصل."},{"i":"lt-11","s":13,"h":"الخطوة 3: المعنى","t":"learn","x":"الصوت المتكبر والواقع النقش بيخاطب العظماء ويطلب منهم اليأس: Look on my Works, ye Mighty, and despair! لكن بعد النقش مباشرة: Nothing beside remains . التناقض ده هو قلب المفارقة. والقصيدة بتقول المعنى بدون ما تعلق عليه."},{"i":"lt-11","s":14,"h":"الخطوة 3: المعنى","t":"learn","x":"قراءتان للمفارقة القراءة الأولى: الجملة دليل غرور الملك، فهو يبدو سخيفا. القراءة التانية: ممكن يكون الملك عارف إنه هيموت، فبيكتب الجملة تذكيرا إن العظيم بينسى. وجود قراءتين هو ما يسميه النقد الجديد غموضا ومفارقة."},{"i":"lt-11","s":15,"h":"الخطوة 3: المعنى","t":"learn","x":"الباقي: الفن اللي فاضل هو مهارة النحات. وفي نهاية الأمر القصيدة نفسها لسه بتتقرا. يعني الفن يعيش بعد السلطة. وده يوضح إزاي الشكل والمعنى مع بعض في وحدة واحدة."},{"i":"lt-11","s":16,"h":"الخطوة 3: المعنى","t":"mc","x":"في قراءة شكلية، الغموض في النقش يعني: ؟ إن الجملة ممكن تفهم بمعنيين متضادين / إن الجملة لا معنى لها / إن الكاتب لا يعرف / إن النقش مكتوب بلغة غريبة . الجملة تحتمل غرور الملك ووعيه بالفناء، وده غموض غني."},{"i":"lt-11","s":17,"h":"الخطوة 3: المعنى","t":"learn","x":"الملخص نبدأ بالشكل، ثم الصورة واللغة، ثم المعنى. في Ozymandias: سونيتة وإطار متعدد الطبقات، صور دمار، تشخيص، مفارقة، وغموض. وكلها تقول: السلطة تزول والفن يبقى."},{"i":"lt-11","s":18,"h":"الخطوة 3: المعنى","t":"recall","x":"اذكر ثلاث أدوات أدبية في Ozymandias وأثرها. . التشخيص يجعل التمثال كإنسان متكبر، المفارقة تظهر التناقض بين نقش الملك وحال التمثال، والصور البصرية تعطي إحساس الدمار."},{"i":"lt-11","s":19,"h":"الخطوة 3: المعنى","t":"write","x":"على نمط امتحانات الكلية: حلل قصيدة Ozymandias تحليلا شكليا (من 6 إلى 7 جمل). . القصيدة سونيتة بالوزن الإيامبي الخماسي، ونمط قافيتها غير تقليدي. الحكاية مروية عبر طبقات: راو ثم مسافر ثم نقش. تقوم على صور الدمار مثل ساقين بلا جذع ووجه محطم. يستخدم الشاعر التشخيص في وصف شفة التمثال الساخرة، والجناس في cold command وboundless and bare. أعمق أدواتها المفارقة بين نقش يدعي العظمة وصحراء خالية. ويبقى النحات والقصيدة، فتقول القصيدة إن السلطة تزول والفن يبقى."},{"i":"lt-12","s":1,"h":"مقدمة","t":"learn","x":"نقرا هاملت من جوه في الدرس ده هنقرا Hamlet بعيون النقد الجديد: مش هنسأل عن إليزابيث ولا إسكس. هنسأل: إيه الأنماط في الصور اللي بتتكرر؟ الفكرة الأساسية: تكرار الصور بيكشف الموضوع."},{"i":"lt-12","s":3,"h":"نمط 1: صور الفخ","t":"learn","x":"الفخاخ في كل مكان في المسرحية صور متعددة لفخاخ. بولونيوس بيحذر أوفيليا إن وعود هاملت springes to catch woodcocks أي فخاخ لاصطياد الطيور. وهاملت بيسمي المسرحية اللي هيعرضها The Mousetrap لأنها the thing wherein I'll catch the conscience of the King ."},{"i":"lt-12","s":4,"h":"نمط 1: صور الفخ","t":"learn","x":"كلوديوس نفسه محاصر كلوديوس بيحس إنه محبوس: O limed soul, that, struggling to be free, art more engaged . limed يعني ملصوق بالغراء زي الطيور. وهاملت يحس إنه be-netted round with villainies أي محاط بالشباك."},{"i":"lt-12","s":5,"h":"نمط 1: صور الفخ","t":"learn","x":"لايرتس والنهاية في النهاية لايرتس اللي بيموت يقول إنه as a woodcock to mine own springe : عصفور وقع في فخه هو. فالفخاخ المعدة للحيوانات هنا بتقع على البشر."},{"i":"lt-12","s":6,"h":"نمط 1: صور الفخ","t":"mc","x":"ليه شبه هاملت مسرحيته ب Mousetrap؟ ؟ لأنها عن الفئران / لأنها فخ ليكشف ضمير الملك / لأنها كوميديا / لأنه يكره المسرح . المسرحية فخ يكشف ذنب كلوديوس."},{"i":"lt-12","s":8,"h":"نمط 2: الكون المريض","t":"learn","x":"الدنمارك سجن من أول مشهد في المسرحية فيه إحساس بعالم مضطرب: ظهور الشبح وقلق الحراس. مارسيلوس يقول: Something is rotten in the state of Denmark . وهاملت يقول لأصحابه: Denmark's a prison ."},{"i":"lt-12","s":9,"h":"نمط 2: الكون المريض","t":"learn","x":"الفساد يمتد للطبيعة هاملت يحس إن فساد الدنمارك بيشمل الطبيعة كلها. الأرض عنده a sterile promontory والسماء a foul and pestilent congregation of vapors . وفي أول مونولوج: 'tis an unweeded garden that grows to seed أي حديقة مهملة تملأها الأعشاب الضارة."},{"i":"lt-12","s":10,"h":"نمط 2: الكون المريض","t":"learn","x":"التوازي النمط ده بيعمل توازي بين فساد الدولة وفساد الطبيعة وفساد الإنسان. يعني المرض مش في شخص واحد. هو إحساس بأن العالم كله مختل."},{"i":"lt-12","s":11,"h":"نمط 2: الكون المريض","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ صور الحديقة المهملة تعبر عن فساد العالم في عين هاملت. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . الحديقة غير المرعية استعارة لفساد العالم."},{"i":"lt-12","s":13,"h":"نمط 3: المعنى المزدوج","t":"learn","x":"كلام بمعنيين كتير من كلام هاملت له معنيان: ظاهر وخفي. لما كلوديوس يسأله ليه حزين، يقول: I am too much in the sun . ظاهرها: الشمس حارة. وكتير من القراء يشوفوا فيها تلاعبا بكلمتي sun و son ، يعني إنه ابن الملك اللي مش مرحب بيه."},{"i":"lt-12","s":14,"h":"نمط 3: المعنى المزدوج","t":"learn","x":"كلوديوس أيضا ثنائي كلوديوس في مشهد الصلاة يقول: And like a man to double business bound, I stand in pause where I shall first begin, and both neglect . هو عايز يتوب وعايز يحتفظ بالتاج والملكة. فالمعنى المزدوج مش لهاملت وحده."},{"i":"lt-12","s":15,"h":"نمط 3: المعنى المزدوج","t":"learn","x":"الصدق في الألغاز هاملت بيتكلم بالألغاز لكن كلامه فعلا بيعبر عن مشاعره. المشكلة إن اللي حواليه مش بيهتموا بالحقائق العميقة. ده مثال على التوتر والمفارقة في النقد الجديد."},{"i":"lt-12","s":16,"h":"نمط 3: المعنى المزدوج","t":"mc","x":"عبارة \"I am too much in the sun\" مثال على: ؟ الصور البصرية فقط / المعنى المزدوج / الحوار العادي بلا معنى / وصف الطقس فقط . العبارة لها معنى حرفي وآخر رمزي، فهي ازدواج في المعنى."},{"i":"lt-12","s":17,"h":"نمط 3: المعنى المزدوج","t":"learn","x":"الملخص نمط الفخاخ، نمط الكون المريض، نمط المعنى المزدوج. الصور المتكررة تكشف موضوع الخداع والفساد والانقسام. وكلها داخل النص نفسه."},{"i":"lt-12","s":18,"h":"نمط 3: المعنى المزدوج","t":"recall","x":"اذكر نمطين من الصور المتكررة في Hamlet ومثالا لكل منهما. . صور الفخاخ مثل The Mousetrap وwoodcock to mine own springe. وصور الكون المريض مثل Denmark's a prison وan unweeded garden."},{"i":"lt-12","s":19,"h":"نمط 3: المعنى المزدوج","t":"write","x":"على نمط امتحانات الكلية: حلل نمط الصور المتكررة في Hamlet من منظور الشكلانية (من 5 إلى 6 جمل). . تعتمد القراءة الشكلية على تتبع الصور المتكررة. في Hamlet نجد صور الفخاخ مثل Mousetrap وspringes وlimed soul، وهي تكشف أن الجميع محاصر. ونجد صور الكون المريض مثل Denmark's a prison وan unweeded garden، لتدل على فساد الدولة والطبيعة. وهناك المعنى المزدوج مثل I am too much in the sun. هذه الأنماط داخل النص تكشف موضوع الخداع والفساد والانقسام."},{"i":"lt-13","s":1,"h":"مقدمة","t":"learn","x":"نفس القصيدة، قراء مختلفين اقرا مع صاحبك قصيدة عن الغربة. أنت مغترب فهتبكي، وهو عمره ما سافر فهيشوفها عادية. إيه الصح؟ نظرية استجابة القارئ Reader-Response Criticism بتقول: المعنى بيحصل لما القارئ يقابل النص."},{"i":"lt-13","s":3,"h":"الفكرة العامة","t":"learn","x":"القارئ شريك النظرية دي ظهرت كرد فعل على ضعف الشكلانية. الشكلانيين شافوا النص كيان مستقل، وهي شافت إن القارئ عنصر أساسي. القراءة مش اكتشاف معنى جاهز، القراءة بتصنع المعنى."},{"i":"lt-13","s":4,"h":"الفكرة العامة","t":"learn","x":"كل قارئ فريد كل قارئ بيجيب تجاربه ومعرفته وقيمه. علشان كده كل قارئ تجربته مختلفة، وبالتالي التفسيرات بتختلف. الاختلاف ده مش غلط، ده نتيجة طبيعية لاختلاف الشخصيات."},{"i":"lt-13","s":5,"h":"الفكرة العامة","t":"mc","x":"استجابة القارئ ظهرت كرد فعل على: ؟ الفيزياء / ضعف الشكلانية في تجاهل القارئ / الماركسية / التفكيكية فقط . أرادت إعادة القارئ للصورة بعدما تجاهلته الشكلانية."},{"i":"lt-13","s":7,"h":"لويز روزنبلات","t":"learn","x":"البداية في أمريكا جذور المدرسة في أمريكا مع لويز روزنبلات Louise Rosenblatt في ثلاثينات القرن العشرين وكتابها Literature as Exploration (1938). ثم في أواخر الستينات والسبعينات، ناقدين زي Wolfgang Iser و Stanley Fish انتقدوا مبادئ النقد الجديد."},{"i":"lt-13","s":8,"h":"لويز روزنبلات","t":"learn","x":"القراءة ك transaction روزنبلات اقترحت إن القراءة \"تبادل\": النص والقارئ مش كيانين منفصلين، كل واحد بيأثر في التاني. النص يكتسب معناه من \"الطريقة اللي بتستجيب بيها عقول القراء وعواطفهم للمنبهات اللغوية في النص\"."},{"i":"lt-13","s":9,"h":"لويز روزنبلات","t":"learn","x":"روزنبلات: قراءتان روزنبلات ميزت بين قراءة تهتم بالمعلومات efferent reading وقراءة تهتم بالتجربة aesthetic reading . في الأولى بتقرا علشان تاخد معلومة. في التانية بتعيش التجربة نفسها."},{"i":"lt-13","s":10,"h":"لويز روزنبلات","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ في هذه القراءة، القصيدة تتناول فعل القراءة نفسه. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. / القراءة اليونغية ترى في الفيلم رحلة نحو التفرد. / روزنبلات ترى أن النص والقارئ منفصلان تماما. . هي ترى القراءة تبادلا يؤثر فيه الطرفان."},{"i":"lt-13","s":12,"h":"وولفغانغ إيزر","t":"learn","x":"إيزر والنص كإطار Wolfgang Iser قال إن النص مش بيكون له معنى قبل أن يختبره القارئ. النص a frame within which the reader must construct the aesthetic object أي إطار بيبني فيه القارئ الموضوع الجمالي. وكتابه The Act of Reading (1978)."},{"i":"lt-13","s":13,"h":"وولفغانغ إيزر","t":"learn","x":"الفراغات gaps إيزر قال إن النص فيه فراغات gaps لا يقولها صراحة، والقارئ بيملأها بخياله وتوقعاته. مثال: لو الراوي قال \"دخل الغرفة وسكت\"، القارئ بيتخيل إيه السبب."},{"i":"lt-13","s":14,"h":"وولفغانغ إيزر","t":"mc","x":"الفراغات (gaps) عند إيزر تعني: ؟ أخطاء مطبعية / أجزاء غير مصرح بها يملؤها القارئ بتخيله / صفحات بيضاء / مسافات بين الكلمات فقط . النص يترك معاني غير مقولة، والقارئ يكملها."},{"i":"lt-13","s":15,"h":"وولفغانغ إيزر","t":"learn","x":"الملخص استجابة القارئ ظهرت ضد الشكلانية. روزنبلات (1938): القراءة تبادل. إيزر (1978): النص إطار وفراغات. في الدرس الجاي: هولاند وبلايش وفيش."},{"i":"lt-13","s":16,"h":"وولفغانغ إيزر","t":"recall","x":"اشرح معنى القراءة ك transaction عند روزنبلات. . القراءة تبادل بين النص والقارئ، كل منهما يؤثر في الآخر، والمعنى يتكون من تفاعلهما لا من النص وحده."},{"i":"lt-13","s":17,"h":"وولفغانغ إيزر","t":"write","x":"على نمط امتحانات الكلية: وضح مفهوم استجابة القارئ مبرزا دور روزنبلات وإيزر (من 5 إلى 6 جمل). . نظرية استجابة القارئ ترى أن المعنى يتكون من تفاعل القارئ مع النص لا من النص وحده، وظهرت كرد فعل على الشكلانية. روزنبلات في Literature as Exploration (1938) رأت القراءة تبادلا بين النص والقارئ. أما إيزر في The Act of Reading فرأى النص إطارا يبني فيه القارئ الموضوع الجمالي، ويملأ ما فيه من فراغات. ولذلك تختلف التفسيرات باختلاف القراء."},{"i":"lt-14","s":1,"h":"مقدمة","t":"learn","x":"القارئ نفسيا واجتماعيا في الدرس اللي فات شفنا روزنبلات وإيزر. النهاردة تلات نقاد تانيين: هولاند، بلايش، فيش. هولاند وبلايش اتجهوا للنفس، وفيش اتجه للمجتمع."},{"i":"lt-14","s":3,"h":"نورمان هولاند","t":"learn","x":"الهوية والنص Norman Holland في كتابه 5 Readers Reading (1975) قال إن كل شخص له \"نواة ثابتة\" في شخصيته اسمها identity theme أي موضوع الهوية. القارئ بيقرا النص من خلال الموضوع ده، فالمعنى انعكاس لشخصيته."},{"i":"lt-14","s":4,"h":"نورمان هولاند","t":"learn","x":"وعي ولاوعي هولاند قال إن القارئ يقرا على مستويين: الوعي، حيث بيبني المعنى، واللاوعي، حيث بيجيب خبراته وارتباطاته. فكل قارئ بيستوعب النص بطريقته الخاصة وبيدافع عن نفسه نفسيا."},{"i":"lt-14","s":5,"h":"نورمان هولاند","t":"mc","x":"مفهوم identity theme مرتبط ب: ؟ هولاند / سوسير / أرسطو / إليوت . هولاند قدمه في 5 Readers Reading."},{"i":"lt-14","s":7,"h":"ديفيد بلايش","t":"learn","x":"النقد الذاتي David Bleich في كتابه Subjective Criticism (1978) قال إن تفسير النص مجرد تعبير عن دوافع القارئ ورغباته الشخصية. علشان نفهم تفسير ما، نبص على استجابتنا الذاتية: إحنا ليه فسرنا بالشكل ده؟"},{"i":"lt-14","s":8,"h":"ديفيد بلايش","t":"learn","x":"من الفرد للمجتمع بلايش قال إن الاستجابة الذاتية هي أساس أي فهم اجتماعي. في أي مجتمع، كل فرد بيشارك باستجابته. وبكده بنتحرك من النفسي للاجتماعي."},{"i":"lt-14","s":9,"h":"ديفيد بلايش","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / بلايش يرى أن التفسير تعبير عن دوافع القارئ الشخصية. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . هذه فكرته الأساسية في Subjective Criticism."},{"i":"lt-14","s":11,"h":"ستانلي فيش","t":"learn","x":"المجتمع التفسيري interpretive community Stanley Fish في كتابه Is There a Text in This Class? (1980) قال إن القارئ بيفسر حسب استراتيجيات المجتمع التفسيري اللي بينتمي له. مثال: طلبة الأدب بيقروا قصيدة بطريقة، والمهندسين بطريقة تانية."},{"i":"lt-14","s":12,"h":"ستانلي فيش","t":"learn","x":"النصوص اجتماعية عند فيش النصوص اجتماعية لأن اللي بيفسرها مجتمعات بقواعد مشتركة. فالمعنى مش فردي بحت ولا نصي بحت. وده يحل جزءا من مشكلة: ليه ناس كتير بتتفق على تفسيرات؟"},{"i":"lt-14","s":13,"h":"ستانلي فيش","t":"mc","x":"مفهوم interpretive community يعني: ؟ كل قارئ لوحده / جماعة تتشارك استراتيجيات التفسير / مجموعة مؤلفين / نص بلا قراء . عند فيش المعنى يتشكل داخل جماعة تفسيرية."},{"i":"lt-14","s":15,"h":"المزايا والعيوب","t":"learn","x":"المزايا النظرية بتربط الأدب بحياة القارئ الحقيقية. وبتشجع القراء على التعبير عن استجاباتهم وبنائها على فهم جماعي. وبتفتح باب لقراءات متعددة."},{"i":"lt-14","s":16,"h":"المزايا والعيوب","t":"learn","x":"العيوب بتهمل نية المؤلف والمعنى اللي قصده. وبتركز بزيادة على القارئ وممكن تبقى ذاتية جدا وتحد من تفسير النصوص. وسؤال كبير بيفضل مفتوح: إزاي نعرف إن قراءة ما صحيحة؟"},{"i":"lt-14","s":17,"h":"المزايا والعيوب","t":"learn","x":"الملخص هولاند: هوية القارئ. بلايش: التفسير ذاتي. فيش: المجتمع التفسيري. المزايا: ربط بالحياة. العيوب: ذاتية وإهمال المؤلف. كلهم متفقين: القارئ لا يغيب."},{"i":"lt-14","s":18,"h":"المزايا والعيوب","t":"recall","x":"قارن بين هولاند وفيش في تفسير اختلاف القراءات. . هولاند يفسر الاختلاف بهوية القارئ النفسية، وفيش يفسره بالمجتمع التفسيري الذي ينتمي إليه القارئ."},{"i":"lt-14","s":19,"h":"المزايا والعيوب","t":"write","x":"على نمط امتحانات الكلية: اذكر مزايا وعيوب نظرية استجابة القارئ (من 4 إلى 5 جمل). . من مزايا النظرية ربط الأدب بتجارب القراء وتشجيعهم على التعبير عن استجاباتهم وبناء التفسير على فهم جماعي. أما عيوبها فإنها قد تهمل نية المؤلف، وتبالغ في دور القارئ فتصبح ذاتية. وهذا قد يحد من إمكان الاتفاق على تفسير صحيح."},{"i":"lt-15","s":1,"h":"مقدمة","t":"learn","x":"نقرا بعيون القارئ النهاردة هنطبق استجابة القارئ على Ozymandias. مفيش إجابة صح أو غلط واحدة، لكن لازم نشرح ونسند كلامنا للنص. وممنوع نكتب: \"القصيدة عجبتني لأنها حلوة\". لازم تحليل."},{"i":"lt-15","s":3,"h":"أسئلة القارئ","t":"learn","x":"أسئلة نسألها لنفسنا إيه علاقة النص بحياتي؟ بيتفق مع نظرتي للعالم ولا بيصطدم بيها؟ إيه اللي بيهمني ويظهر في القصيدة؟ وإزاي بتخاطب مجتمعي أو طبقتي؟ وبعدين: استمتعت بيها كعمل فني ولا لأ؟"},{"i":"lt-15","s":4,"h":"أسئلة القارئ","t":"learn","x":"مثال على إجابة ضعيفة وإجابة قوية ضعيفة: \"عجبتني القصيدة لأنها حلوة\". قوية: \"السطر Nothing beside remains خلاني أفكر في أماكن اتدمرت زي ما كنت أحس أيام الأزمة، لأنه بيدمج العظمة بالفقد.\" الإجابة القوية بتستند لسطر وتربطه بتجربة."},{"i":"lt-15","s":5,"h":"أسئلة القارئ","t":"mc","x":"أي إجابة أنسب في نقد استجابة القارئ؟ ؟ القصيدة حلوة / سطر Nothing beside remains ذكرني بمكان فقد قيمته، ووجدت المعنى قريبا من تجربتي / مش فاكر / الشاعر مشهور . الإجابة تربط دليلا من النص بتجربة شخصية."},{"i":"lt-15","s":7,"h":"القصيدة عن القراءة","t":"learn","x":"القصيدة نفسها عن القراءة نقطة ذكية: القصيدة عن عملية القراءة. المسافر بيقرا نقشا على تمثال، والنحات قرأ وجه الملك، والراوي بيسمع الحكاية، وإحنا بنقرا القصيدة. يعني فيه أربعة \"قراء\" على التوالي."},{"i":"lt-15","s":8,"h":"القصيدة عن القراءة","t":"learn","x":"القارئ الأول: النحات النحات read مشاعر الملك those passions read وخلدها في الحجر. يعني النحت نفسه قراءة. وهنا مسألة: ازاي نعرف إنه قرأ \"بشكل جيد\" well ؟"},{"i":"lt-15","s":9,"h":"القصيدة عن القراءة","t":"learn","x":"المفارقة في القراءة المسافر بيقول إن الباقي بس شظايا من التمثال. فإزاي يعرف إن النحات قرأ مشاعر الملك قراءة جيدة؟ السؤال ده بيوري إن \"القراءة الجيدة\" مسألة معقدة، وفيها لعب بالكلمات."},{"i":"lt-15","s":10,"h":"القصيدة عن القراءة","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / في هذه القراءة، القصيدة تتناول فعل القراءة نفسه. / أنهي جملة من دول غلط؟ . النحات والمسافر والراوي والقارئ كلهم قراء."},{"i":"lt-15","s":12,"h":"اختلاف التفسير","t":"learn","x":"اختلاف النقاد ناقد زي جراهام هاف قال إن Ozymandias \"قصيدة واضحة ومباشرة\" بصورة واحدة. نقاد تانيين شافوا فيها مفارقة وغموض وتناقض، وبالتالي أكتر من قراءة. وده بيثبت نقطة استجابة القارئ: القراء بيختلفوا."},{"i":"lt-15","s":13,"h":"اختلاف التفسير","t":"learn","x":"قراءتان للنقش القراءة الأولى: النقش غرور سخيف. القراءة التانية: ملك عارف إنه هيموت وبيكتب تذكير بفناء العظماء. نفس النقش، بس القراءتين تعتمد على موقع القارئ."},{"i":"lt-15","s":14,"h":"اختلاف التفسير","t":"learn","x":"اختلاف القارئ المصري قارئ مصري ممكن يربط القصيدة بآثار بلده وأهرامات الجيزة وتماثيل رمسيس، ويحس بمزيج فخر وحزن. وقارئ بريطاني ممكن يربطها بامبراطورية بلاده. السياق بيصنع المعنى."},{"i":"lt-15","s":15,"h":"اختلاف التفسير","t":"mc","x":"أيهما يعبر عن استجابة القارئ؟ ؟ حفظ أبيات القصيدة / ربط القصيدة بتجربة وسياق القارئ مع استشهاد بالنص / كتابة سيرة شيلي / عد الأسطر . الاستجابة تربط النص بالقارئ مع الدليل."},{"i":"lt-15","s":16,"h":"اختلاف التفسير","t":"learn","x":"الملخص نسأل: علاقة النص بحياتي؟ مع استشهاد من النص. القصيدة نفسها عن القراءة وفيها أربعة قراء. قراءتان للنقش، والقارئ هو من يختار. ولا إجابة واحدة صحيحة."},{"i":"lt-15","s":17,"h":"اختلاف التفسير","t":"recall","x":"وضح كيف تتناول القصيدة نفسها موضوع القراءة. . النحات قرأ وجه الملك، والمسافر قرأ النقش، والراوي سمع الحكاية، ونحن نقرأ القصيدة، فهي سلسلة من أفعال القراءة."},{"i":"lt-15","s":18,"h":"اختلاف التفسير","t":"write","x":"على نمط امتحانات الكلية: طبق استجابة القارئ على قصيدة Ozymandias (من 5 إلى 6 جمل). . تفتح استجابة القارئ باب القراءات المتعددة ل Ozymandias. يمكن أن يرى قارئ في نقش الملك غرورا سخيفا، ويرى آخر وعي ملك بفنائه. القصيدة نفسها تتناول القراءة: النحات قرأ وجه الملك، والمسافر قرأ النقش، ونحن نقرأ القصيدة. وقد يربطها قارئ مصري بآثار بلده فيجد مزيجا من الفخر والحزن. لذلك يعتمد المعنى على تفاعل القارئ مع النص."},{"i":"lt-16","s":1,"h":"مقدمة","t":"learn","x":"ليه بتحلم بحاجات غريبة؟ كلنا بنحلم بحاجات مش مفهومة. فرويد قال إن وراها رغبات مدفونة جوانا، بنكبتها علشان نعيش مع الناس. والنقد النفسي Psychoanalytic Criticism بيطبق نفس الفكرة على الأدب."},{"i":"lt-16","s":3,"h":"فرويد والأدب","t":"learn","x":"إيه هو النقد النفسي؟ النقد النفسي بيقرأ العمل الأدبي كتعبير عن العقل الداخلي. بيتساءل عن الذكريات والدوافع والمخاوف المخفية اللي بتشكل النص، خصوصا في الشخصيات الخيالية. وبيستخدم علم النفس لفهم دوافع المؤلف أو الشخصيات."},{"i":"lt-16","s":4,"h":"فرويد والأدب","t":"learn","x":"سيجموند فرويد Sigmund Freud نمساوي، طبيب أعصاب، عاش من 1856 إلى 1939. وتاريخ وفاته 1939 بالظبط، وده بيتلخبط في بعض الكتب. في الأصل التحليل النفسي علاج لمرضى بيعانوا نفسيا، يساعدهم يفهموا مصدر أعراضهم."},{"i":"lt-16","s":5,"h":"فرويد والأدب","t":"learn","x":"اللاوعي The unconscious فرويد قال إن معظم عملياتنا العقلية لاواعية. بنتصرف بدوافع مش واخدين بالنا منها. ومن هنا جت أهمية اللاوعي. فرويد استخدم أمثلة من الأدب في تشخيص مرضاه، زي عقدة أوديب Oedipus complex ."},{"i":"lt-16","s":6,"h":"فرويد والأدب","t":"mc","x":"فرويد عاش: ؟ من 1846 إلى 1939 / من 1856 إلى 1939 / من 1901 إلى 1981 / من 1856 إلى 1930 . الصحيح 1856 إلى 1939."},{"i":"lt-16","s":8,"h":"الجهاز النفسي","t":"learn","x":"ثلاثة أجزاء فرويد قسم النفس لثلاثة: الهو id والأنا ego والأنا الأعلى superego . الفكرة: الهو شيطان صغير، والأنا الأعلى ملاك، والأنا حكم بينهم."},{"i":"lt-16","s":9,"h":"الجهاز النفسي","t":"learn","x":"الهو id مصدر الطاقة النفسية، ويحكمه مبدأ اللذة pleasure principle . هو مصدر الرغبات والعدوان، من غير أخلاق ولا قانون. لو الهو لوحده، الإنسان يعمل أي حاجة بدون اعتبار للنتيجة."},{"i":"lt-16","s":10,"h":"الجهاز النفسي","t":"learn","x":"الأنا ego الأنا هو الجزء العقلاني. بيحكمه مبدأ الواقع reality principle ، وبيكون وسيط بين العالم الداخلي والعالم الخارجي. وهو اللي بيقول: \"استنى، مش دلوقتي\"."},{"i":"lt-16","s":11,"h":"الجهاز النفسي","t":"learn","x":"الأنا الأعلى superego هو الضمير والمعايير الأخلاقية، وأغلبه لاواعي. بيكبت رغبات الهو غير المقبولة اجتماعيا. يحكمه مبدأ الأخلاق morality principle . وهو مصدر الشعور بالذنب والفخر."},{"i":"lt-16","s":12,"h":"الجهاز النفسي","t":"mc","x":"الجزء الذي يحكمه مبدأ اللذة: ؟ الأنا / الأنا الأعلى / الهو / الوعي . الهو يسعى لإشباع الرغبات فورا."},{"i":"lt-16","s":13,"h":"الجهاز النفسي","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ الأنا (ego) هو الجزء الذي يوازن بين الهو والأنا الأعلى. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . الأنا وسيط يوازن بين الرغبة والأخلاق والواقع."},{"i":"lt-16","s":15,"h":"لاكان","t":"learn","x":"جاك لاكان Jacques Lacan فرنسي (1901 إلى 1981) ربط فرويد بالبنيوية. قال إن اللاوعي \"مبني مثل لغة\"، وإن دخول الإنسان اللغة هو دخول العالم الاجتماعي. لما تقدر تسمي نفسك وتفرق بينك وبين غيرك، بتدخل عالم القواعد وكبت الغرائز."},{"i":"lt-16","s":16,"h":"لاكان","t":"learn","x":"الملخص فرويد 1856-1939: اللاوعي والكبت. id وego وsuperego. لاكان 1901-1981: اللاوعي مثل اللغة. وبكده النقد النفسي بيقرأ ما وراء النص."},{"i":"lt-16","s":17,"h":"لاكان","t":"recall","x":"اشرح الأجزاء الثلاثة للنفس عند فرويد. . الهو مصدر الرغبات ويحكمه مبدأ اللذة. الأنا عقلاني ويحكمه مبدأ الواقع. الأنا الأعلى الضمير ويحكمه مبدأ الأخلاق."},{"i":"lt-16","s":18,"h":"لاكان","t":"write","x":"على نمط امتحانات الكلية: اشرح تقسيم فرويد للنفس البشرية (من 5 إلى 6 جمل). . قسم فرويد النفس إلى الهو والأنا والأنا الأعلى. الهو مصدر الطاقة والرغبات ويحكمه مبدأ اللذة، وهو بلا أخلاق. الأنا هو الجزء العقلاني ويحكمه مبدأ الواقع، ويتوسط بين العالم الداخلي والخارجي. الأنا الأعلى هو الضمير والمعايير الأخلاقية ويكبت رغبات الهو غير المقبولة. ويوازن الأنا بين الاثنين."},{"i":"lt-17","s":1,"h":"مقدمة","t":"learn","x":"خلاف بين أستاذ وتلميذ كارل يونغ Carl Jung كان قريب من فرويد، لكن اختلف معاه. التقيا سنة 1907 واشتغلا مع بعض سنوات. يونغ رفض فكرة إن الجنس هو المحرك الوحيد للاوعي، وطور نظريته الخاصة."},{"i":"lt-17","s":3,"h":"طبقات النفس","t":"learn","x":"ثلاث طبقات يونغ قسم النفس لثلاث طبقات: الوعي المباشر immediate consciousness ، واللاوعي الشخصي personal unconscious ، واللاوعي الجمعي collective unconscious . الأولى هي الأنا والقناع الذي نقدمه للناس، والتانية الذكريات المنسية والمكبوتة، والتالتة مشتركة بين البشر كلهم."},{"i":"lt-17","s":4,"h":"طبقات النفس","t":"learn","x":"القناع persona Persona معناها قناع الممثل. هو الوجه اللي بنقدمه للمجتمع: في الشغل غير البيت وغير الأصحاب. وده جزء من الوعي المباشر."},{"i":"lt-17","s":5,"h":"طبقات النفس","t":"learn","x":"اللاوعي الجمعي هو نظام نفسي عام مشترك بين كل الناس بغض النظر عن ثقافتهم. فيه نماذج أولية archetypes موجودة من الأساس، مش مكتسبة. وكأن البشرية عندها \"ذاكرة قديمة\" مشتركة."},{"i":"lt-17","s":6,"h":"طبقات النفس","t":"mc","x":"اللاوعي الجمعي عند يونغ هو: ؟ ذكريات منسية خاصة بالفرد / نظام نفسي مشترك بين كل البشر / قناع اجتماعي / حلم اليوم السابق . اللاوعي الجمعي عام ومشترك."},{"i":"lt-17","s":8,"h":"النماذج الأولية","t":"learn","x":"إيه هي ال archetypes؟ النماذج الأولية هي أنماط فطرية بتولد نفس الأفكار والصور والأساطير عند الناس بغض النظر عن طبقتهم أو دينهم أو زمنهم. مثال: فكرة البطل اللي بيخرج في رحلة ويواجه شر ويرجع منتصر موجودة في أساطير شعوب كتير."},{"i":"lt-17","s":9,"h":"النماذج الأولية","t":"learn","x":"الظل The Shadow هو الجانب المظلم اللي بنرفض نعترف بيه في أنفسنا. غالبا بيظهر في الأدب كالجانب المظلم للبطل. مثال: الجانب المظلم للدكتور جيكل هو مستر هايد."},{"i":"lt-17","s":10,"h":"النماذج الأولية","t":"learn","x":"الرجل الحكيم The Wise Old Man هو النموذج اللي بيظهر لما نحتاج بصيرة أو نصيحة ومش قادرين نوصلها بمفردنا. يعني المرشد. في الحكايات: ساحر أو معلم أو جد حكيم."},{"i":"lt-17","s":11,"h":"النماذج الأولية","t":"learn","x":"الأم The Mother هي صورة الأم الكونية: رعاية وحنان. ممكن تتسقط على أي امرأة بتقوم بدور الأم في حياة البطل. وهي مش مجرد أم حقيقية، هي نمط."},{"i":"lt-17","s":12,"h":"النماذج الأولية","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / الظل (Shadow) هو الجانب المظلم الذي يرفض الإنسان الاعتراف به. / أنهي جملة من دول غلط؟ . الظل يضم الصفات المكبوتة التي يرفضها الفرد."},{"i":"lt-17","s":14,"h":"التفرد","t":"learn","x":"التفرد Individuation هدف الإنسان عند يونغ هو التفرد: يوصل لشخصية متكاملة ومتوازنة بين الوعي واللاوعي، وبيقبل كل جوانب نفسه، الإيجابي والسلبي. ولازم يواجه ظله ويعرف نماذجه الأولية علشان يوصل ليه."},{"i":"lt-17","s":15,"h":"التفرد","t":"mc","x":"الهدف النهائي للإنسان عند يونغ هو: ؟ الثراء / التفرد وتكامل الشخصية / محو اللاوعي / إنكار الظل . التفرد هو توازن الوعي واللاوعي."},{"i":"lt-17","s":16,"h":"التفرد","t":"learn","x":"الفرق عن فرويد فرويد: اللاوعي شخصي ومكبوت وجنسي في الأساس. يونغ: فيه طبقة جمعية مشتركة، والأنماط الأولية، وهدف الإنسان تكامل نفسه. وكلاهما أثر في النقد الأدبي."},{"i":"lt-17","s":17,"h":"التفرد","t":"learn","x":"الملخص يونغ التقى فرويد 1907 واختلف. ثلاث طبقات: وعي، لاوعي شخصي، لاوعي جمعي. نماذج: الظل، الرجل الحكيم، الأم. الهدف: التفرد. وده بيتحول في النقد لدراسة رحلة البطل."},{"i":"lt-17","s":18,"h":"التفرد","t":"recall","x":"اذكر ثلاث طبقات للنفس عند يونغ وثلاثة نماذج أولية. . الوعي المباشر، واللاوعي الشخصي، واللاوعي الجمعي. والنماذج: الظل، والرجل الحكيم، والأم."},{"i":"lt-17","s":19,"h":"التفرد","t":"write","x":"على نمط امتحانات الكلية: قارن بين فرويد ويونغ في نظرتهما للاوعي (من 5 إلى 6 جمل). . فرويد يرى اللاوعي شخصيا قائما على الرغبات المكبوتة، وللجنس دور أساسي فيه. أما يونغ فاختلف معه بعد لقائهما سنة 1907، ورأى أن للنفس ثلاث طبقات: الوعي واللاوعي الشخصي واللاوعي الجمعي. اللاوعي الجمعي مشترك بين البشر وفيه نماذج أولية مثل الظل والرجل الحكيم والأم. وهدف الإنسان عند يونغ هو التفرد والتوازن بين الوعي واللاوعي."},{"i":"lt-18","s":1,"h":"مقدمة","t":"learn","x":"نطبق على نصين النهاردة تطبيقين: فرويدي على هاملت، ويونغي على رحلة البطل في فيلم وثائقي. كل واحد هيورينا طريقة تانية للنظر. والمدرسة النفسية بتسأل: إيه المخفي تحت السطح؟"},{"i":"lt-18","s":3,"h":"فرويد وهاملت","t":"learn","x":"عقدة أوديب في هاملت كتير من النقاد النفسيين شافوا إن هاملت عنده أشهر عقدة أوديب في الأدب. مات أبوه وأمه تزوجت عمه بسرعة. فشعر إن عالمه اتفكك، وغضبه موجه ناحية الأم والعم في نفس الوقت."},{"i":"lt-18","s":4,"h":"فرويد وهاملت","t":"learn","x":"لماذا يتأخر هاملت؟ تفسير نفسي مشهور: هاملت يتأخر عن الانتقام لأن كلوديوس نفذ رغبة مكبوتة جوا هاملت نفسه: قتل الأب والزواج بالأم. فهاملت يحس بالذنب. ده تفسير مقترح مش حقيقة مثبتة. وفيه تفسيرات تانية للتأخير، منها التردد الأخلاقي والشك في الشبح."},{"i":"lt-18","s":5,"h":"فرويد وهاملت","t":"learn","x":"الهو والأنا والأنا الأعلى هاملت ممزق: الهو عايز ينتقم فورا، والأنا الأعلى بيخوفه من الذنب والقتل، والأنا بيحاول يوازن. وهو الجانب الذي يفسر تردده. وكلوديوس في مشهد الصلاة بيقع في صراع مشابه بين الرغبة والذنب."},{"i":"lt-18","s":6,"h":"فرويد وهاملت","t":"mc","x":"حسب القراءة الفرويدية، تردد هاملت سببه: ؟ الجبن فقط / صراع نفسي لاواعي مرتبط بعقدة أوديب والذنب / قلة المال / جهله بالجريمة . التفسير الفرويدي يربط التردد بصراع لاواعي."},{"i":"lt-18","s":8,"h":"يونغ ورحلة البطل","t":"learn","x":"فيلم Murderball الفيلم الوثائقي Murderball (2005) عن لاعبي رجبي الكراسي المتحركة المصابين بشلل رباعي. فاز بجوائز في مهرجان صندانس. وبعض النقاد قرأوه بنظرة يونغية: كل لاعب في رحلة نحو تكامل الشخصية."},{"i":"lt-18","s":9,"h":"يونغ ورحلة البطل","t":"learn","x":"الظل الظل هو الصفات اللي الشخص بيرفض يعترف بيها. اللاعبين بيحسوا بعجزهم وبيرفضوا يعترفوا بحاجتهم لمساعدة. المواجهة مع الظل أول اختبار شجاعة على طريق التفرد، بحسب يونغ."},{"i":"lt-18","s":10,"h":"يونغ ورحلة البطل","t":"learn","x":"الرجل الحكيم والأم في الفيلم، أحد اللاعبين بيحكي إن أبوه كان بيتعامل مع ضحك الأطفال بخفة. الأب هنا بيقوم بدور الرجل الحكيم المرشد. والأمهات بيدعموا الأبطال في رحلتهم، وده دور الأم الأولى."},{"i":"lt-18","s":11,"h":"يونغ ورحلة البطل","t":"learn","x":"النهاية: التفرد أحد اللاعبين يقول إن إصابته كانت \"أفضل حاجة حصلت\" له. القراءة اليونغية بتشوف ده وصول لقبول الذات. والفيلم بيبني أسطورة جديدة بتكسر الصورة القديمة عن الإعاقة كضعف."},{"i":"lt-18","s":12,"h":"يونغ ورحلة البطل","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / هيلبرون ترى أن جيرترود امرأة ضعيفة لا تعبر عن نفسها. / القراءة اليونغية ترى في الفيلم رحلة نحو التفرد. . اللاعبون يواجهون الظل ويرشدهم الحكيم وتدعمهم الأم."},{"i":"lt-18","s":13,"h":"يونغ ورحلة البطل","t":"mc","x":"أي نموذج أولي يمثل الأب المرشد في الفيلم؟ ؟ الظل / الرجل الحكيم / الأم / القناع . الأب يقدم النصيحة وقت الحاجة."},{"i":"lt-18","s":14,"h":"يونغ ورحلة البطل","t":"learn","x":"حدود التطبيق النفسي النقد النفسي ممكن يتحول لتشخيص الكاتب بدل قراءة العمل. وكمان تفسيراته صعب إثباتها. فنكتب دائما: one possible reading أي قراءة محتملة."},{"i":"lt-18","s":15,"h":"يونغ ورحلة البطل","t":"learn","x":"الملخص هاملت فرويديا: أوديب وصراع لاواعي. Murderball يونغيا: الظل والرجل الحكيم والأم والتفرد. والحدود: تفسيرات محتملة لا حقائق."},{"i":"lt-18","s":16,"h":"يونغ ورحلة البطل","t":"recall","x":"اذكر مثالا على تطبيق فرويدي ومثالا على تطبيق يونغي. . فرويدي: تفسير تردد هاملت بعقدة أوديب والذنب. يونغي: قراءة Murderball كرحلة نحو التفرد بمواجهة الظل وإرشاد الرجل الحكيم."},{"i":"lt-18","s":17,"h":"يونغ ورحلة البطل","t":"write","x":"على نمط امتحانات الكلية: طبق النقد النفسي على عمل أدبي أو فني مع مصطلحين على الأقل (من 5 إلى 6 جمل). . يمكن قراءة Hamlet فرويديا: يرى بعض النقاد أن تردده سببه صراع لاواعي مرتبط بعقدة أوديب والذنب، فالهو يريد الانتقام والأنا الأعلى يخيفه، والأنا يحاول التوازن. ويمكن قراءة فيلم Murderball يونغيا كرحلة نحو التفرد، حيث يواجه البطل ظله، ويرشده الرجل الحكيم، وتدعمه الأم. وهذه قراءات محتملة وليست حقائق مثبتة."},{"i":"lt-19","s":1,"h":"مقدمة","t":"learn","x":"أي حاجة ممكن تتقرا هل ينفع نقرا إعلان تليفزيون، أو فيلم، أو أغنية مهرجانات، زي ما نقرا قصيدة؟ الدراسات الثقافية Cultural Studies بتقول: أيوه. كل شيء في الثقافة نص، وكل نص بيحمل أفكار وقوى."},{"i":"lt-19","s":3,"h":"إيه هي؟","t":"learn","x":"صعب نعرفها من الصعب تعريف الدراسات الثقافية لأن كلمة ثقافة culture نفسها صعب تعريفها. وهي مش منهج واحد، لكنها مجموعة ممارسات واتجاهات وأسئلة. الناقد Patrick Brantlinger وصفها بإنها مجموعة اتجاهات متقاربة بلا أجندة ثابتة."},{"i":"lt-19","s":4,"h":"إيه هي؟","t":"learn","x":"من إيه تتكون؟ الدراسات الثقافية بتجمع عناصر من الماركسية، والتاريخانية الجديدة، والنسوية، ودراسات الجندر، والأنثروبولوجيا، ودراسات العرق، ونظرية الفيلم، وعلم الاجتماع، والثقافة الشعبية، وما بعد الاستعمار. يعني تخصصات كتيرة تهتم بالقوى الاجتماعية اللي بتجمع الناس أو تفرقهم."},{"i":"lt-19","s":6,"h":"الأهداف الأربعة","t":"learn","x":"الهدف الأول: تتخطى حدود التخصص الدراسات الثقافية مش بتحبس نفسها في الأدب أو التاريخ. بتعبر بين التخصصات وتتناول صراعات اجتماعية وسياسية متنوعة. علشان كده الباحث فيها ممكن يقرا رواية وإعلان وقانون في بحث واحد."},{"i":"lt-19","s":7,"h":"الأهداف الأربعة","t":"learn","x":"الهدف الثاني: ملتزمة سياسيا النقاد الثقافيين بيشوفوا نفسهم \"معارضين\" لهياكل السلطة. بيسألوا عن عدم المساواة، حتى في الفصل الدراسي، وبيحاولوا يعيدوا ترتيب العلاقات بين الثقافات المهيمنة والمهمشة. وبما إن المعنى والذات مبنيين ثقافيا، فيمكن إعادة بناءهم."},{"i":"lt-19","s":8,"h":"الأهداف الأربعة","t":"learn","x":"الهدف الثالث: لا فرق بين الراقي والشعبي الدراسات الثقافية مبتفرقش بين الثقافة الراقية high culture والثقافة الشعبية popular culture . الاتنين بيدرسوا في علاقتهم بباقي الممارسات الثقافية. يعني أغنية شعبية ممكن تتحلل بنفس الجدية زي قصيدة كلاسيكية."},{"i":"lt-19","s":9,"h":"الأهداف الأربعة","t":"learn","x":"الهدف الرابع: دراسة الإنتاج مش بس نحلل العمل المنتج، لكن كمان وسائل الإنتاج: مين بيمول الفنان؟ مين بينشر؟ مين بيشتري؟ إزاي بيتسوق؟ السؤال ده ورثته من النقد الماركسي."},{"i":"lt-19","s":10,"h":"الأهداف الأربعة","t":"mc","x":"أي من هذه ليس هدفا من أهداف الدراسات الثقافية؟ ؟ تجاوز حدود التخصص / الالتزام السياسي / الفصل بين الثقافة الراقية والشعبية / دراسة وسائل الإنتاج . الدراسات الثقافية ترفض هذا الفصل."},{"i":"lt-19","s":11,"h":"الأهداف الأربعة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. / الدراسات الثقافية منهج واحد محدد له قواعد ثابتة. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. / أنهي جملة من دول صحيحة؟ . هي مجموعة اتجاهات وممارسات وليست منهجا واحدا."},{"i":"lt-19","s":13,"h":"الفائدة والجدل","t":"learn","x":"ليه تدرسها؟ جيرالد جراف وجيمس فيلان قالوا إن ثقافة المستقبل هتقدر الناس اللي بتتعامل بإنتاجية مع الاختلاف والصراع الثقافي. والدراسة بالجدل تدرب على المواطنة. وبتسمح لك تقرا من \"موقعك الخاص\" مش من وجهة نظر موضوعية مزعومة."},{"i":"lt-19","s":14,"h":"الفائدة والجدل","t":"learn","x":"حروب الثقافة culture wars فيه خلاف كبير: ناس بتدافع عن الإنسانية humanism كأساس للحضارة الغربية والديمقراطية الحديثة، وناس بتقول إن الثقافة الغربية متأثرة بالعنصرية والتمييز والاستعمار. والنقاد الماركسي تيري إيجلتون شاف إن أزمة العلوم الإنسانية نتيجة فشلها هي نفسها."},{"i":"lt-19","s":15,"h":"الفائدة والجدل","t":"learn","x":"الملخص الدراسات الثقافية مجموعة ممارسات. أهدافها: تخطي التخصصات، التزام سياسي، لا فرق بين راقي وشعبي، دراسة الإنتاج. والجدل مفتوح حولها."},{"i":"lt-19","s":16,"h":"الفائدة والجدل","t":"recall","x":"اذكر ثلاثة من أهداف الدراسات الثقافية. . تتخطى حدود التخصصات، وتلتزم سياسيا ضد عدم المساواة، ولا تفرق بين الثقافة الراقية والشعبية، وتدرس وسائل الإنتاج."},{"i":"lt-19","s":17,"h":"الفائدة والجدل","t":"write","x":"على نمط امتحانات الكلية: عرف الدراسات الثقافية واذكر أهدافها (من 5 إلى 6 جمل). . الدراسات الثقافية ليست منهجا واحدا بل مجموعة ممارسات واتجاهات تتناول القوى الاجتماعية والثقافية. تجمع عناصر من الماركسية والنسوية والتاريخانية الجديدة والأنثروبولوجيا وغيرها. أهدافها: تخطي حدود التخصصات، والالتزام السياسي في مواجهة عدم المساواة، ورفض الفصل بين الثقافة الراقية والشعبية، ودراسة وسائل إنتاج الأعمال الثقافية."},{"i":"lt-20","s":1,"h":"مقدمة","t":"learn","x":"ثلاث طرق لدراسة الثقافة الدراسات الثقافية ليها ثلاث مسارات رئيسية: المادية الثقافية البريطانية، والتاريخانية الجديدة، والتعددية الثقافية الأمريكية. النهاردة الأولى. وهي مرتبطة بالفكر الماركسي."},{"i":"lt-20","s":3,"h":"من أرنولد لويليامز","t":"learn","x":"تعريف الثقافة إدوارد تايلور Edward Burnett Tylor في كتابه Primitive Culture (1871) عرف الثقافة بإنها \"الكل المعقد اللي يشمل المعرفة والمعتقد والفن والأخلاق والقانون والعرف وأي قدرات يكتسبها الإنسان كعضو في المجتمع\". التعريف ده وسع معنى الثقافة بحيث يشمل كل حاجة، مش بس الفنون الراقية."},{"i":"lt-20","s":4,"h":"من أرنولد لويليامز","t":"learn","x":"ريموند ويليامز Raymond Williams ويليامز ماركسي من أسرة عاملة، قال إن الثقافة \"عادية\" culture is ordinary ، وإنها موجودة عند الطبقة العاملة زي ما هي عند النخبة. وقال: There are no masses; there are only ways of seeing people as masses أي مفيش \"جماهير\"، فيه بس طرق نشوف بيها الناس كجماهير."},{"i":"lt-20","s":5,"h":"من أرنولد لويليامز","t":"learn","x":"ليفيس والتراث العظيم في الخمسينات في بريطانيا بدأت المادية الثقافية تتشكل مع F. R. Leavis اللي تأثر بأرنولد. دعا لنشر الأدب العظيم، شكسبير وميلتون، علشان يرفع الحس الأخلاقي. واعتبر الثقافة الجماهيرية تهديدا. وويليامز وهوغارت Richard Hoggart اتفقوا على قيمة الأدب الكلاسيكي لكن اختلفوا مع نخبويته."},{"i":"lt-20","s":6,"h":"من أرنولد لويليامز","t":"mc","x":"من قال إن الثقافة \"عادية\" وموجودة عند الطبقة العاملة؟ ؟ إليوت / ريموند ويليامز / ليفيس / دريدا . ويليامز دافع عن ثقافة الطبقة العاملة."},{"i":"lt-20","s":8,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"الهيمنة Hegemony بمساعدة مفكرين ماركسيين زي أدورنو وهوركهايمر وجرامشي، ظهر مفهوم الهيمنة: علاقات سيطرة مش دايما ظاهرة. ويليامز عرفها بإنها \"إحساس بالواقع عند معظم الناس، يصعب تجاوزه\". يعني السيطرة بتشتغل من خلال ما نعتبره \"طبيعي\"."},{"i":"lt-20","s":9,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"ألتوسير والأيديولوجيا Ideology Louis Althusser قال إن الأيديولوجيا بتشكلنا كأفراد، وبتخلينا نحس إننا أحرار بينما نحن نعيد إنتاج النظام. ووصفها ب\"سوء تعرف\" misrecognition بتعمل علينا من غير ما ندري."},{"i":"lt-20","s":10,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"بارت والعلامات Roland Barthes Roland Barthes وعلم السيمياء semiotics : ندرس الثقافة كعلامات ونقرأها زي ما نقرا الأدب. الإعلان والفيلم والموضة كلها علامات بتحمل أيديولوجيا. وبذلك المعنى بقى ساحة للصراع الطبقي."},{"i":"lt-20","s":11,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"باختين وتعدد المعنى polysemy ميخائيل باختين Mikhail Bakhtin شاف إن المعنى بيتولد حواريا dialogically داخل الصراع الاجتماعي. وأفكار تعدد المعنى polysemy ساعدت على فهم إن نفس المنتج الثقافي يعني حاجات مختلفة في سياقات مختلفة. ملحوظة: باختين مش من الشكلانيين الروس، هو بالعكس انتقد الشكلانية. بعض الكتب بتخلط ده."},{"i":"lt-20","s":12,"h":"الهيمنة والأيديولوجيا","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ استجابة القارئ بتؤكد إن المعنى بيتكون من تفاعل القارئ والنص. / باختين من أعضاء مدرسة الشكلانية الروسية الأصلية. / أنهي جملة من دول صحيحة؟ / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. . باختين وجماعته انتقدوا الشكلانية وطوروا فكرة الحوارية."},{"i":"lt-20","s":13,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"بورديو ورأس المال الرمزي عالم الاجتماع الفرنسي Pierre Bourdieu قال إن الأغنياء بيحتاجوا يعرضوا رأس مال رمزي symbolic capital كالفن واسم العائلة علشان يحافظوا على سيطرتهم المادية. مثال: صور الهند في كتابات كيبلنغ زمن الاستعمار البريطاني بتبدو بريئة لكنها بتدعم فكرة تفوق البيض."},{"i":"lt-20","s":14,"h":"الهيمنة والأيديولوجيا","t":"mc","x":"الهيمنة (hegemony) تعني: ؟ حكم بالقوة العسكرية فقط / سيطرة غير ظاهرة تقبل كأنها طبيعية / انتخابات حرة / تعدد الأحزاب . الهيمنة سيطرة تعمل عبر القبول وإحساس \"الواقع\"."},{"i":"lt-20","s":15,"h":"الهيمنة والأيديولوجيا","t":"learn","x":"الملخص من تايلور (1871) لويليامز: الثقافة عادية. ليفيس: التراث العظيم. هيمنة (جرامشي وويليامز)، أيديولوجيا (ألتوسير)، علامات (بارت)، حوارية (باختين)، رأس مال رمزي (بورديو). وكلها أدوات لقراءة السلطة في الثقافة."},{"i":"lt-20","s":16,"h":"الهيمنة والأيديولوجيا","t":"recall","x":"وضح الفرق بين رؤية ليفيس ورؤية ويليامز للثقافة. . ليفيس رأى أن الأدب العظيم يرفع الذوق الأخلاقي وأن الثقافة الجماهيرية تهديد. ويليامز رأى أن الثقافة عادية وموجودة عند الطبقة العاملة أيضا."},{"i":"lt-20","s":17,"h":"الهيمنة والأيديولوجيا","t":"write","x":"على نمط امتحانات الكلية: اشرح مفهوم الهيمنة والأيديولوجيا في المادية الثقافية (من 5 إلى 6 جمل). . الهيمنة سيطرة غير ظاهرة تقبل كأنها طبيعية، وعرفها ويليامز بأنها إحساس بالواقع يصعب تجاوزه. أما الأيديولوجيا عند ألتوسير فهي سوء تعرف يشكل الأفراد ويجعلهم يعيدون إنتاج النظام دون وعي. ويساعد بارت بعلم العلامات على قراءة الثقافة كنص يحمل أيديولوجيا، ويضيف بورديو أن رأس المال الرمزي يحافظ على السيطرة المادية."},{"i":"lt-21","s":1,"h":"مقدمة","t":"learn","x":"المسار الثالث بعد المادية الثقافية البريطانية والتاريخانية الجديدة، المسار التالت هو التعددية الثقافية الأمريكية American Multiculturalism . وهي بتدرس إزاي الهويات المختلفة بتشكل الأدب والمجتمع."},{"i":"lt-21","s":3,"h":"لمحة تاريخية","t":"learn","x":"أمريكا الستينات في منتصف الستينات حصلت أحداث عنف عنصرية كبيرة في مدن أمريكية كتيرة. وكان قانون الحقوق المدنية سنة 1964 وقانون حق التصويت سنة 1965. ورغم القوانين، التمييز استمر في مجالات كتيرة، وده شكل أرضية للتعددية الثقافية."},{"i":"lt-21","s":4,"h":"لمحة تاريخية","t":"learn","x":"تغير الأرقام زواج الأمريكيين من أعراق مختلفة ازداد بعد ما كان محظورا في ولايات كتيرة. في 1967 المحكمة العليا ألغت القوانين اللي بتمنع الزواج بين الأعراق. وده طرح سؤالا: هل \"العرق\" فئة طبيعية أم اجتماعية؟"},{"i":"lt-21","s":6,"h":"العرق كبناء اجتماعي","t":"learn","x":"هل العرق حقيقة بيولوجية؟ كتير من المؤرخين وعلماء الاجتماع بيشوفوا العرق race بناء اجتماعيا اخترعه الناس لتوزيع المكانة والامتيازات. مفيش علامات جينية للعرق زي ما فيه للجنس. وعالم الوراثة ريتشارد ليونتين Richard Lewontin قال في 1972 إن أغلب الاختلافات الجينية بتكون داخل المجموعات مش بينها."},{"i":"lt-21","s":7,"h":"العرق كبناء اجتماعي","t":"learn","x":"هنري لويس جيتس الناقد الأمريكي الأفريقي Henry Louis Gates Jr. بيكتب كلمة \"race\" بين علامتي تنصيص، لأنها بتدعي إنها تصنيف موضوعي، بينما هي مجاز trope خطير للاختلاف المطلق. وقال إننا بنستخدم اللغة بشكل بيدعي الاختلاف الطبيعي، وده فعل لغوي خطير بيزود المشكلة."},{"i":"lt-21","s":8,"h":"العرق كبناء اجتماعي","t":"mc","x":"جيتس يكتب كلمة race بين علامتي تنصيص لأنه: ؟ يحب الأقواس / يرى أنها تصنيف يدعي الموضوعية وهو مجاز اجتماعي / يعتبرها حقيقة بيولوجية / لا يعرف معناها . يرى أن المصطلح يخفي بناء اجتماعيا."},{"i":"lt-21","s":10,"h":"أسئلة التعددية الثقافية في الأدب","t":"learn","x":"أسئلة مفتوحة أي \"ثقافات\" نضمها للمنهج؟ مين يقرر؟ إيه الثقافة؟ لازم تكون عرقية؟ ولا ممكن مجموعات تانية؟ ومين \"نحن\" ومين \"هم\" أو الآخر the other ؟ وهل ندمج الأدب العرقي في التيار الرئيسي أم نحافظ على استقلاله؟"},{"i":"lt-21","s":11,"h":"أسئلة التعددية الثقافية في الأدب","t":"learn","x":"مفارقة الاحتفاء احتفاءنا ب\"الآخر\" ممكن يؤكد بنية المركز والهامش: ثقافة رئيسية بتسمح بدراسة ثقافات هامشية داخلها. فالتعددية نفسها مليانة مفارقات."},{"i":"lt-21","s":12,"h":"أسئلة التعددية الثقافية في الأدب","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ الدراسات الأدبية في التعددية الثقافية تتفق على إجابة واحدة لمن يقرر أي ثقافات تدخل المنهج. / هيلبرون تراها ذكية وشجاعة وقادرة على التعبير. / النسوية الفرنسية النفسية تركز على الكبت (repression). / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. . الأسئلة مفتوحة وخلافية."},{"i":"lt-21","s":13,"h":"أسئلة التعددية الثقافية في الأدب","t":"learn","x":"مثال من الأدب النقد التعددي بيقرا أعمال كتاب من خلفيات متنوعة: أفريقية أمريكية، لاتينية، آسيوية. وبيسأل عن الهوية والذاكرة والحدود. وكمان بيسأل: كيف تمثل هذه الجماعات في أعمال مؤلفين من خارجها؟"},{"i":"lt-21","s":14,"h":"أسئلة التعددية الثقافية في الأدب","t":"learn","x":"الملخص التعددية الثقافية الأمريكية: سياق الحقوق المدنية. العرق بناء اجتماعي. جيتس: race بين تنصيص. أسئلة: من يقرر المنهج؟ ومن \"الآخر\"؟ وفيها مفارقة الاحتفاء بالهامش."},{"i":"lt-21","s":15,"h":"أسئلة التعددية الثقافية في الأدب","t":"recall","x":"وضح لماذا يعتبر الكثيرون العرق بناء اجتماعيا. . لأنه لا توجد علامات جينية للعرق، وأغلب الاختلافات الجينية داخل المجموعات لا بينها، فالعرق صنفه الناس لتوزيع المكانة والامتيازات."},{"i":"lt-21","s":16,"h":"أسئلة التعددية الثقافية في الأدب","t":"write","x":"على نمط امتحانات الكلية: ما التعددية الثقافية وما الأسئلة التي تثيرها في الأدب؟ (من 5 إلى 6 جمل). . التعددية الثقافية اتجاه أمريكي يدرس إزاي الهويات المختلفة تشكل الأدب والمجتمع، ونشأ في سياق الحقوق المدنية. يرى كثيرون العرق بناء اجتماعيا لا حقيقة بيولوجية، ويضع جيتس كلمة race بين علامتي تنصيص. تثير في الأدب أسئلة: أي ثقافات تدرس، ومن يقرر، ومن الآخر. وتكشف مفارقة أن الاحتفاء بالآخر قد يؤكد ثنائية المركز والهامش."},{"i":"lt-22","s":1,"h":"مقدمة","t":"learn","x":"هاملت والسلطة نقرا Hamlet بنظرة الدراسات الثقافية: مين صاحب السلطة؟ مين المهمش؟ وإزاي السلطة بتحرك الناس؟ وهنركز على شخصيتين مهمشتين: روزنكرانتز وجيلدنستيرن."},{"i":"lt-22","s":3,"h":"خطاب الملك والسلطة","t":"learn","x":"خطاب روزنكرانتز في المشهد التالت، روزنكرانتز يلقي خطاب جميل عن الملك: حياة الملك هي a massy wheel fixed on the summit of the highest mount أي عجلة ضخمة على قمة جبل عالي، والآلاف من الأشياء الصغيرة معلقة فيها. لما تقع، كلهم يقعوا معاها. Never alone did the King sigh but with a general groan ."},{"i":"lt-22","s":4,"h":"خطاب الملك والسلطة","t":"learn","x":"ثقافة السلطة الخطاب ده تلخيص لمفهوم السلطة الملكية في عصر إليزابيث: الملك مركز الكون، وسقوطه يهدد الكل. والخطاب جميل شعريا، لكنه كمان وسيلة لتبرير السلطة ولخدمتها."},{"i":"lt-22","s":5,"h":"خطاب الملك والسلطة","t":"mc","x":"خطاب العجلة الضخمة يعبر عن: ؟ حب روزنكرانتز لهاملت / فكرة أن مصير الجميع مرتبط بالملك / وصف جبل حقيقي / نصيحة زراعية . العجلة والملحقات الصغيرة صورة للتبعية للملك."},{"i":"lt-22","s":7,"h":"المهمشان","t":"learn","x":"روزنكرانتز وجيلدنستيرن زميلان لهاملت من جامعة فيتنبرغ. كلوديوس يستدعيهم علشان يتجسسوا على هاملت. هاملت يحس بالأمر ويصدهم. اسماهما يبدوان مثل ألقاب مبهرجة ويضيعان الفردية، حسب بعض النقاد."},{"i":"lt-22","s":8,"h":"المهمشان","t":"learn","x":"رسالة الإعدام كلوديوس يرسلهم مع هاملت لإنجلترا بخطاب يأمر بإعدام هاملت. هاملت يغير الرسالة ويكتب اسميهما، فيعدمان بدلا منه. ولما يسأله هوراشيو، يرد هاملت: \"مش على ضميري\" They are not near my conscience ."},{"i":"lt-22","s":9,"h":"المهمشان","t":"learn","x":"الإسفنجة هاملت يشبه روزنكرانتز بإسفنجة تمتص رضا الملك ومنافعه وسلطته. ويقول إن الملك لما يحتاج ما جمعوا بيعصرهم فيجفوا. التشبيه ده بيكشف إزاي السلطة بتستعمل الناس الصغار وتتخلص منهم."},{"i":"lt-22","s":10,"h":"المهمشان","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ في المسرحية يستخدم روزنكرانتز وجيلدنستيرن كأداة لدى السلطة ثم يضحى بهما. / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . هما يخدمان الملك ويدفعان الثمن."},{"i":"lt-22","s":12,"h":"السلطة في تاريخ إنجلترا","t":"learn","x":"تاريخ الدم الجمهور الإليزابيثي كان يعرف تاريخا من العنف على قمة السلطة: خلع وإعدام ريتشارد الثاني، واتهامات ضد ريتشارد الثالث، وإعدام توماس مور، وإعدام إيرل إسكس سنة 1601، وإعدام ماري ملكة الاسكتلنديين. وبعد جيل، إعدام تشارلز الأول. فالسلطة خطر دائم."},{"i":"lt-22","s":13,"h":"السلطة في تاريخ إنجلترا","t":"learn","x":"السلطة والسياسة شكسبير في Hamlet يعكس صراع القوة. كلوديوس نفسه يقول: Madness in great ones must not unwatched go أي جنون العظماء لازم يتراقب. وبنفس المنطق: سلطة العظماء لازم تتراقب. وده سؤال الدراسات الثقافية."},{"i":"lt-22","s":14,"h":"السلطة في تاريخ إنجلترا","t":"mc","x":"أي سؤال تطرحه الدراسات الثقافية على Hamlet؟ ؟ كم عدد كلمات المسرحية؟ / كيف تعمل السلطة وتهمش الصغار؟ / ما لون مسرح العرض؟ / أين دفن شكسبير؟ . تحليل السلطة والتهميش هو صلب المنهج."},{"i":"lt-22","s":15,"h":"السلطة في تاريخ إنجلترا","t":"learn","x":"الملخص الدراسات الثقافية تسأل عن السلطة. خطاب العجلة يبرر السلطة الملكية. روزنكرانتز وجيلدنستيرن أداة وضحية. التاريخ الإنجليزي يوضح عنف السلطة. وهاملت: سلطة تحتاج مراقبة."},{"i":"lt-22","s":16,"h":"السلطة في تاريخ إنجلترا","t":"recall","x":"وضح كيف يكشف مصير روزنكرانتز وجيلدنستيرن آلية عمل السلطة. . هما أداة بيد الملك، يتجسسان بأمره، ثم يضحي بهما في النهاية، فالسلطة تستخدم الصغار وتتخلص منهم."},{"i":"lt-22","s":17,"h":"السلطة في تاريخ إنجلترا","t":"write","x":"على نمط امتحانات الكلية: اقرأ Hamlet قراءة ثقافية مركزا على السلطة والتهميش (من 5 إلى 6 جمل). . تقرأ الدراسات الثقافية Hamlet عبر السلطة. يعرض خطاب روزنكرانتز عن عجلة الملك فكرة أن مصير الجميع مرتبط بالملك. ويبدو روزنكرانتز وجيلدنستيرن شخصيتين مهمشتين تستخدمان للتجسس ثم يضحى بهما حين يغير هاملت الرسالة. ويشبههما هاملت بإسفنجة تمتص رضا الملك ثم تعصر. وتذكر المسرحية بتاريخ إنجلترا العنيف حيث السلطة خطر، ولهذا تراقب."},{"i":"lt-23","s":1,"h":"مقدمة","t":"learn","x":"سؤال قديم لما بتقرا رواية كاتبها راجل، المرأة فيها غالبا بتبقى حبيبة أو أم أو خادمة. هل ده صدفة؟ النقد النسوي Feminist Criticism بيسأل السؤال ده. وبيبحث عن صورة المرأة في الأدب، وعن الكاتبات اللي اتنسوا."},{"i":"lt-23","s":3,"h":"التعريف","t":"learn","x":"مبادئ أكتر منها تقنية النقد النسوي بدأ كمنهج واضح أواخر الستينات. هو مش تقنية معينة لقراءة النص، بل مجموعة مبادئ. وهو رد فعل على سيطرة الرجال وتبعية المرأة في المؤسسات الغربية، ومنها المؤسسات الأدبية. ومعظم النسويات بيشوفوا إن الثقافة أبوية patriarchal ، يعني منظمة لصالح الرجال."},{"i":"lt-23","s":4,"h":"التعريف","t":"learn","x":"إيه اللي بتسأل عنه؟ كيف صورت النساء ولماذا؟ ما معنى حضورهن في القصة؟ ما صعوبات الكاتبات؟ وكيف نحدد تقليدا أدبيا نسائيا؟ وبتبحث عن أعمال كاتبات منسيات علشان تعيد اكتشافهن."},{"i":"lt-23","s":5,"h":"التعريف","t":"mc","x":"النقد النسوي في أصله: ؟ تقنية واحدة لقراءة النص / مجموعة مبادئ تسأل عن السلطة والجندر / نظرية عن الإيقاع / نظرية عن القافية . هو منهج مبادئ لا تقنية واحدة."},{"i":"lt-23","s":7,"h":"تاريخ النقد النسوي","t":"learn","x":"المراحل الثلاث عند شوالتر إيلين شوالتر Elaine Showalter حددت ثلاث مراحل لتطور الأدب النسائي: مرحلة \"الأنثوية\" feminine (1840-1880) وفيها قلدت الكاتبات التقاليد السائدة. ومرحلة \"النسوية\" feminist (1880-1920) وفيها احتجت الكاتبات ودافعن عن حقوق الأقلية. ومرحلة \"الأنثى\" female (من 1920 حتى الآن) وفيها اكتشاف نصوص النساء بدل الاعتماد على كشف التحيز."},{"i":"lt-23","s":8,"h":"تاريخ النقد النسوي","t":"learn","x":"الموجة المعاصرة شوالتر ترى أن النقد النسوي المعاصر نما مع الحركة النسائية المعاصرة وأعمال سيمون دي بوفوار وكيت ميليت وبيتي فريدان. وقبلهم كاتبات مثل جورج إليوت وماري ولستونكرافت وفيرجينيا وولف."},{"i":"lt-23","s":9,"h":"تاريخ النقد النسوي","t":"learn","x":"دي بوفوار في كتابها The Second Sex (1949) سألت: ما المرأة؟ وكيف تبنى؟ إجابتها: الرجال يبنونها مختلفة عنهم. والرجل هو من يحدد الإنسان العادي، والمرأة هي \"الآخر\". وده أسس لقضايا النسوية الحديثة."},{"i":"lt-23","s":10,"h":"تاريخ النقد النسوي","t":"learn","x":"فريدان وميليت Betty Friedan في The Feminine Mystique (1963) كشفت صورة ربة البيت السعيدة في الضواحي الأمريكية. و Kate Millett في Sexual Politics (1970) كانت أول عمل نقدي نسوي واسع القراءة. ميزت بين الجنس البيولوجي والجندر المكتسب ثقافيا، وقالت إن جوهر السياسة هو القوة، وأعمق قوة في مجتمعنا هي سيطرة الرجال."},{"i":"lt-23","s":11,"h":"تاريخ النقد النسوي","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / ميليت في Sexual Politics ميزت بين الجنس البيولوجي (sex) والجندر (gender). / أنهي جملة من دول غلط؟ / أنهي جملة من دول غلط؟ . تمييز الجنس البيولوجي عن الجندر المكتسب ثقافيا أساس في كتابها."},{"i":"lt-23","s":12,"h":"تاريخ النقد النسوي","t":"learn","x":"القارئ المقاوم ميليت اعتبرت نفسها resisting reader أي قارئة مقاومة: قرأت أعمال دي. إتش. لورانس ونورمان ميلر وهنري ميلر وجان جينيه، ورأت أنهم يشوهون الشخصيات النسائية. وبذلك هاجمت الشكلانية السائدة وقتها."},{"i":"lt-23","s":13,"h":"تاريخ النقد النسوي","t":"mc","x":"كتاب The Second Sex ل: ؟ ميليت / فريدان / دي بوفوار / شوالتر . The Second Sex لسيمون دي بوفوار (1949)."},{"i":"lt-23","s":14,"h":"تاريخ النقد النسوي","t":"learn","x":"الصمت والصوت تيلي أولسن في كتابها Silences (1978) تكلمت عن صمت النساء عبر القرون وعوائق إبداعهن. وفي نفس الوقت الصمت أحيانا يكون مقاومة، مثل \"الحقيقة المائلة\" عند إميلي ديكنسون. وشخصيات هادئة مثل جين آير عند شارلوت برونتي."},{"i":"lt-23","s":15,"h":"تاريخ النقد النسوي","t":"learn","x":"الملخص النقد النسوي: أواخر الستينات، مبادئ أكتر من تقنية. شوالتر: ثلاث مراحل. دي بوفوار 1949، فريدان 1963، ميليت 1970. القارئ المقاوم. وهدفهم: كشف الأبوية وإعادة اكتشاف الكاتبات."},{"i":"lt-23","s":16,"h":"تاريخ النقد النسوي","t":"recall","x":"اذكر مراحل شوالتر الثلاث مع تواريخها. . الأنثوية 1840-1880، والنسوية 1880-1920، والأنثى من 1920 حتى الآن."},{"i":"lt-23","s":17,"h":"تاريخ النقد النسوي","t":"write","x":"على نمط امتحانات الكلية: تتبع تاريخ النقد النسوي وأهم رواده (من 5 إلى 6 جمل). . بدأ النقد النسوي منهجا واضحا في أواخر الستينات وهو يقوم على مبادئ لا تقنية واحدة، ويرى الثقافة أبوية. حددت شوالتر ثلاث مراحل للأدب النسائي: الأنثوية والنسوية والأنثى. من رواده دي بوفوار في The Second Sex (1949) وفريدان في The Feminine Mystique (1963) وميليت في Sexual Politics (1970) التي ميزت بين الجنس والجندر ورأت القوة جوهر السياسة. وهدفهم كشف الأبوية وإعادة اكتشاف كاتبات منسيات."},{"i":"lt-24","s":1,"h":"مقدمة","t":"learn","x":"أربع ممارسات النقد النسوي متنوع جدا. في الكتاب بيتجمع في أربع ممارسات رئيسية: دراسات الجندر، والنسوية الماركسية، والنسوية النفسية، ودراسات الأقليات. النهاردة الأولى للتالتة، مع التركيز على النسوية الفرنسية."},{"i":"lt-24","s":3,"h":"دراسات الجندر","t":"learn","x":"الجندر والاختلاف فيه نسويات بيركزن على الاختلاف بين الجنسين، وفيه اللي بيقولوا إن فكرة الاختلاف هي سبب اضطهاد النساء وعايزين يتجاوزوها. ودراسات الجندر بتهتم بصفات الذكورة والأنوثة أكتر من الجنس البيولوجي."},{"i":"lt-24","s":4,"h":"دراسات الجندر","t":"learn","x":"هل للكتابة جنس؟ النسويات بيحددوا استراتيجيات كتابة مرتبطة بالجنس: موضوع، مفردات، أسلوب، صور، شخصيات. وبيسألوا: إيه اللي يقدر؟ هل اليوميات أقل شأنا من الرواية الواقعية؟ وفيه خلاف كبير، والاستثناءات في كل مكان، فالتعميم خطر."},{"i":"lt-24","s":5,"h":"دراسات الجندر","t":"mc","x":"دراسات الجندر تهتم ب: ؟ الجنس البيولوجي فقط / صفات الذكورة والأنوثة كما تصوغها الثقافة / القافية / الجغرافيا . الجندر هو الهوية المكتسبة ثقافيا."},{"i":"lt-24","s":7,"h":"النسوية الماركسية","t":"learn","x":"الجندر والطبقة النسوية الماركسية بتربط القراءة بالواقع الاجتماعي. بتشوف النظام الرأسمالي استغلالي اقتصاديا وجنسيا، فبتدرس الطبقة والجندر معا. وبتهتم بشروط إنتاج النصوص: النشر والتوزيع."},{"i":"lt-24","s":8,"h":"النسوية الماركسية","t":"learn","x":"القيمة الأدبية الماركسيين بيشوفوا إن القيمة الأدبية مش خاصية ثابتة، بل نتاج معتقدات واحتياجات المجتمع. وده اتنقد لإنه بيتجاهل الجماليات والعبقرية. ليليان روبنسون ردت: الشكل والأسلوب مش مستقلين عن الأيديولوجيا."},{"i":"lt-24","s":10,"h":"النسوية النفسية","t":"learn","x":"النقد الأمريكي والفرنسي والإنجليزي شوالتر لخصت: النسوية الإنجليزية ماركسية وتركز على الاضطهاد oppression . الفرنسية نفسية وتركز على الكبت repression . الأمريكية نصية وتركز على التعبير expression . وكلها بحثت عن لغة تنقذ \"الأنثوي\" من أن يكون مرادفا للدونية."},{"i":"lt-24","s":11,"h":"النسوية النفسية","t":"learn","x":"جيلبرت وجوبار ساندرا جيلبرت وسوزان جوبار درسا صور المرأة في أعمال جين أوستن وماري شيلي وأخوات برونتي وجورج إليوت. من أفكارهما: شخصية \"المجنونة في العلية\" madwoman تمثل جزءا من نفس الكاتبة الغاضبة. وبتقابلها شخصية \"الملاك\" angel المثالية. كتابهما The Madwoman in the Attic (1979)."},{"i":"lt-24","s":12,"h":"النسوية النفسية","t":"learn","x":"لاكان والخيالي من لاكان جت فكرة \"المرحلة الخيالية\" the Imaginary : مرحلة بتسبق اللغة، الطفل فيها مش منفصل عن أمه. دخول اللغة هو دخول \"النظام الرمزي\" the Symbolic ، حيث كل شيء منفصل. وفي النسوية الفرنسية بتتحول المرحلة الخيالية لمكان رمزي للأنثوي. (ده شرح مبسط لفكرة معقدة)."},{"i":"lt-24","s":13,"h":"النسوية النفسية","t":"mc","x":"أنهي جملة من دول صحيحة؟ ؟ أنهي جملة من دول غلط؟ / النسوية الفرنسية النفسية تركز على الكبت (repression). / النقد الجديد والتاريخانية الجديدة متفقان على قراءة النص بمعزل عن التاريخ. / أنهي جملة من دول غلط؟ . هذا وصف شوالتر للنسوية الفرنسية."},{"i":"lt-24","s":14,"h":"النسوية النفسية","t":"learn","x":"سيكسو وكريستيفا هيلين سيكسو Hélène Cixous دعت للكتابة الأنثوية écriture féminine واقترحت \"صوت الأم\" كمصدر لقوة الكتابة النسائية. وجوليا كريستيفا Julia Kristeva ميزت بين \"السيميائي\" semiotic المرتبط بالأم و\"الرمزي\" المرتبط بقانون الأب. وكلاهما يربط بين الشخصي والاجتماعي."},{"i":"lt-24","s":15,"h":"النسوية النفسية","t":"mc","x":"مفهوم écriture féminine مرتبط ب: ؟ هيلين سيكسو / فريدان / فرويد / ميليت . سيكسو من أبرز دعاة الكتابة الأنثوية."},{"i":"lt-24","s":16,"h":"النسوية النفسية","t":"learn","x":"الملخص دراسات الجندر، والنسوية الماركسية، والنفسية: جيلبرت وجوبار، لاكان، سيكسو، كريستيفا. شوالتر: إنجليزية = اضطهاد، فرنسية = كبت، أمريكية = تعبير."},{"i":"lt-24","s":17,"h":"النسوية النفسية","t":"recall","x":"وضح الفرق بين النسوية الإنجليزية والفرنسية والأمريكية عند شوالتر. . الإنجليزية ماركسية وتركز على الاضطهاد، والفرنسية نفسية وتركز على الكبت، والأمريكية نصية وتركز على التعبير."},{"i":"lt-24","s":18,"h":"النسوية النفسية","t":"write","x":"على نمط امتحانات الكلية: اشرح اتجاهين من اتجاهات النقد النسوي المعاصر (من 5 إلى 6 جمل). . من الاتجاهات النسوية الماركسية التي تربط الجندر بالطبقة وتنتقد استغلال الرأسمالية للنساء وتهتم بظروف إنتاج النصوص. ومنها النسوية النفسية، مثل جيلبرت وجوبار اللذين درسا صورة المجنونة والملاك، والفرنسيات مثل سيكسو وكريستيفا اللاتي تأثرن بلاكان ودعون إلى الكتابة الأنثوية. وقد لخصت شوالتر الفروق بأن الإنجليزية تركز على الاضطهاد والفرنسية على الكبت والأمريكية على التعبير."},{"i":"lt-25","s":1,"h":"مقدمة","t":"learn","x":"هاملت من منظور النساء كل قراءاتنا ل Hamlet كانت بتركز على هاملت. النهاردة نسأل: إيه دور جيرترود وأوفيليا؟ وإزاي صورة المرأة اتشكلت من وجهة نظر ابن غاضب؟ وده سؤال النقد النسوي."},{"i":"lt-25","s":3,"h":"هاملت وكراهية الأنوثة","t":"learn","x":"الصراع النفسي هاملت عنده صراع بين صورتين لأبيه: الأب الميت وكلوديوس. فبيتوجه غضبه نحو أمه وأوفيليا أكتر من أي حد. ومن هنا بنقرا كراهيته للنساء كعرض لصراع نفسي أعمق."},{"i":"lt-25","s":4,"h":"هاملت وكراهية الأنوثة","t":"learn","x":"الجنس والعيب هاملت يرى الجنس شيئا شريرا: اشمئزازه من كلوديوس وأمه وأوفيليا وبغضه لنفسه لأنه جاء من جسد أمه. وأقسى كراهيته تجيء من مشاعره الجنسية المتناقضة اللي تهدده من لاوعيه. وده بيفسر إن كراهية النساء عنده بتتحول لتدمير ذاتي."},{"i":"lt-25","s":5,"h":"هاملت وكراهية الأنوثة","t":"mc","x":"حسب القراءة النسوية، كراهية هاملت للنساء: ؟ تعبير عن صراع نفسي وجنسي يتجه نحو أمه وأوفيليا / مجرد صدفة / لا وجود لها / سببها حب المال . القراءة تربطها بصراعه النفسي."},{"i":"lt-25","s":7,"h":"جيرترود","t":"learn","x":"صورة هاملت لأمه هاملت يقول لأمه إنها Frailty, thy name is woman أي الضعف اسمك امرأة. ويرى أنها خانت أباه وبدلت Hyperion ب satyr أي الإله بحيوان شهواني. ومعظم النقاد شافوا جيرترود من عيون ابنها."},{"i":"lt-25","s":8,"h":"جيرترود","t":"learn","x":"إعادة تقييم عند هيلبرون الناقدة كارولين هيلبرون Carolyn Heilbrun قدمت مراجعة مهمة في Hamlet's Mother and Other Women (1990). قالت إن جيرترود مش \"طيبة لكن سطحية\"، لكنها امرأة كلامها محدد وفيه شجاعة. وهي بتعبر عن نفسها بوضوح، وقادرة على رؤية الواقع والتعبير عنه."},{"i":"lt-25","s":9,"h":"جيرترود","t":"learn","x":"أدلة من النص جيرترود طلبت من هاملت يجلس جنبها، وحاولت تدمجه في البلاط. وخطابها عن موت أوفيليا مثال على الرقة واللياقة. وعندما يهاجمها هاملت تقول إنها لا تعرف عن القتل شيئا: What have I done, that thou dar'st wag thy tongue in noise so rude against me?"},{"i":"lt-25","s":10,"h":"جيرترود","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ وظيفتها تقديم تجربة خاصة تلفت النظر لشكل اللغة نفسها. / هي ترى القراءة تبادلا يؤثر فيه الطرفان. / هيلبرون ترى أن جيرترود امرأة ضعيفة لا تعبر عن نفسها. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. . هيلبرون تراها ذكية وشجاعة وقادرة على التعبير."},{"i":"lt-25","s":11,"h":"جيرترود","t":"mc","x":"ماذا فعلت هيلبرون في دراسة جيرترود؟ ؟ أكدت صورة ابنها عنها / أعادت قراءتها من كلامها هي نفسها / ألغت الشخصية / نقلتها لمسرحية أخرى . قرأت الشخصية من أقوالها بدل عيون ابنها."},{"i":"lt-25","s":13,"h":"أوفيليا والسياق","t":"learn","x":"الجسد المتنازع عليه النقد النسوي يرى جيرترود \"الأرض التي تدور عليها كل معارك المسرحية\": جسدها محل نزاع بين ابنها وزوجيها والبلاط. هي مصدر النزاعات لكنها لم تدخل أيا منها بإرادتها، كما يرى بعض النقاد."},{"i":"lt-25","s":14,"h":"أوفيليا والسياق","t":"learn","x":"أوفيليا أوفيليا تطيع أباها بدون سؤال، وتتعرض لقسوة هاملت. وهي مثال على موقع المرأة في المجتمع الإليزابيثي: خاضعة لأبيها وأخيها ولحبيبها. وبعض القراءات النسوية تعتبر جنونها وموتها نتيجة ضغوط من حولها."},{"i":"lt-25","s":15,"h":"أوفيليا والسياق","t":"learn","x":"الليل والمرأة في المشهد الأول الليل يوصف بلغة أنثوية: الشبح في womb of earth وسحر witch has power to charm ، وبيهرب من صياح cock الديك الذكر. وكأن الخوف من الاضطراب مربوط بالخوف من الأنثوي."},{"i":"lt-25","s":16,"h":"أوفيليا والسياق","t":"learn","x":"الملخص القراءة النسوية ل Hamlet: كراهية النساء عند هاملت كعرض نفسي. جيرترود صورة مشوهة عند ابنها، وهيلبرون أعادت قراءتها. أوفيليا مثال على خضوع المرأة. والجسد الأنثوي ساحة صراع."},{"i":"lt-25","s":17,"h":"أوفيليا والسياق","t":"recall","x":"وضح كيف أعادت هيلبرون قراءة جيرترود. . رأت أن جيرترود ليست سطحية، بل ذكية وشجاعة وتعبر عن نفسها بوضوح، فقرأتها من كلامها لا من عيون هاملت."},{"i":"lt-25","s":18,"h":"أوفيليا والسياق","t":"write","x":"على نمط امتحانات الكلية: اقرأ شخصيتي جيرترود وأوفيليا في Hamlet قراءة نسوية (من 5 إلى 6 جمل). . ترى القراءة النسوية أن صورة جيرترود في المسرحية ترى غالبا من عيون ابنها الذي يشتم ضعفها. لكن هيلبرون أعادت تقييمها فرأتها امرأة ذكية وشجاعة وتعبر عن نفسها بوضوح. وجسد جيرترود ساحة نزاع بين ابنها وزوجيها. أما أوفيليا فتخضع لأبيها ولحبيبها وتتعرض لقسوة هاملت، وبعض النقاد يربطون جنونها وموتها بضغوط من حولها."},{"i":"lt-26","s":1,"h":"مقدمة","t":"learn","x":"الصورة الكاملة وصلنا لآخر درس. هنجمع كل المدارس في صورة واحدة، ونتدرب على أسئلة المقارنة، اللي بتجي كتير في الامتحانات. الفكرة: كل مدرسة بتجاوب على سؤال مختلف: مين صاحب المعنى؟"},{"i":"lt-26","s":3,"h":"جدول المقارنة","t":"learn","x":"المعنى عند مين؟ التاريخي والسيري: المعنى عند المؤلف وزمنه. الشكلانية والنقد الجديد: المعنى في النص نفسه. استجابة القارئ: المعنى في تفاعل القارئ والنص. التحليل النفسي: المعنى في اللاوعي (المؤلف أو الشخصية أو القارئ). الماركسية والنسوية والدراسات الثقافية: المعنى مرتبط بالسلطة والطبقة والجندر."},{"i":"lt-26","s":4,"h":"جدول المقارنة","t":"learn","x":"ماذا تقول عن المؤلف؟ التاريخي: المؤلف أساسي. النقد الجديد: نية المؤلف مغالطة قصدية. استجابة القارئ: المؤلف أقل أهمية من القارئ. التفكيكية: المؤلف لا يملك المعنى. التحليل النفسي: ممكن نفهم المؤلف ودوافعه، لكن بحذر."},{"i":"lt-26","s":5,"h":"جدول المقارنة","t":"mc","x":"أي مدرسة تعتبر نية المؤلف مغالطة؟ ؟ النقد الجديد / التاريخي والسيري / التحليل النفسي / النسوية . المغالطة القصدية مصطلح من النقد الجديد."},{"i":"lt-26","s":6,"h":"جدول المقارنة","t":"mc","x":"أي مدرسة ترى أن المعنى يتكون من تفاعل القارئ والنص؟ ؟ الشكلانية / استجابة القارئ / البنيوية / النقد التاريخي . هذا تعريف استجابة القارئ."},{"i":"lt-26","s":8,"h":"نماذج مقارنة","t":"learn","x":"مقارنة 1: الشكلانية والتاريخي الشكلانية: تركز على النص وتقنياته وتتجاهل السيرة والتاريخ. التاريخي: يربط النص بحياة المؤلف وزمنه. الفرق في مصدر المعنى: داخل النص أم خارجه. وتوضيح: ظهرت الشكلانية جزئيا كرد فعل على الاعتماد الزائد على السيرة."},{"i":"lt-26","s":9,"h":"نماذج مقارنة","t":"learn","x":"مقارنة 2: الشكلانية واستجابة القارئ الشكلانية: النص كيان مستقل والمعنى موضوعي. استجابة القارئ: المعنى يتكون من تجربة القارئ، فتتعدد القراءات. وهي رد فعل مباشر على ضعف الشكلانية في تجاهل القارئ."},{"i":"lt-26","s":10,"h":"نماذج مقارنة","t":"learn","x":"مقارنة 3: التاريخانية الجديدة والنقد الجديد النقد الجديد يقرأ النص بمعزل عن التاريخ. التاريخانية الجديدة تراه جزءا من ثقافة زمنه وتقرأ النص والوثيقة معا. وبرضه التاريخانية الجديدة تختلف عن التاريخي القديم لأنها ترى التاريخ نفسه تفسيرا."},{"i":"lt-26","s":11,"h":"نماذج مقارنة","t":"learn","x":"مقارنة 4: فرويد ويونغ فرويد: لاوعي شخصي ومكبوت، الهو والأنا والأنا الأعلى. يونغ: لاوعي جمعي ونماذج أولية، والهدف التفرد. وكلاهما يقرأ الأدب كتعبير عن عقل لا نعيه كله."},{"i":"lt-26","s":12,"h":"نماذج مقارنة","t":"learn","x":"مقارنة 5: الماركسية والنسوية والدراسات الثقافية الماركسية: الطبقة والإنتاج. النسوية: الجندر والنظام الأبوي. الدراسات الثقافية: السلطة والهيمنة في كل أشكال الثقافة. وكلها اجتماعية، وكلها بتسأل: من يملك السلطة؟ ومن يهمش؟"},{"i":"lt-26","s":13,"h":"نماذج مقارنة","t":"mc","x":"أنهي جملة من دول غلط؟ ؟ النقد التاريخي بيشترط معرفة السياق التاريخي والاجتماعي. / هيلبرون تراها ذكية وشجاعة وقادرة على التعبير. / أفلاطون خاف من الشعر، وأرسطو دافع عنه وشرح فائدته. / النقد الجديد والتاريخانية الجديدة متفقان على قراءة النص بمعزل عن التاريخ. . النقد الجديد يفصل النص، والتاريخانية الجديدة تربطه بالثقافة."},{"i":"lt-26","s":15,"h":"تطبيق: نص واحد وكل العدسات","t":"learn","x":"Ozymandias بكل العدسات تاريخي: رمسيس الثاني ومصر القديمة والنشر 1818. شكلي: سونيتة ومفارقة وغموض. قارئ: القراءات المتعددة للنقش والقراء الأربعة داخل القصيدة. وبالتالي كل عدسة بتفتح باب مختلف على نفس القصيدة."},{"i":"lt-26","s":16,"h":"تطبيق: نص واحد وكل العدسات","t":"learn","x":"Hamlet بكل العدسات تاريخي: عرش انتخابي ومسرحية الانتقام. شكلي: صور الفخ والكون المريض. نفسي: أوديب والذنب. ثقافي: السلطة وروزنكرانتز. نسوي: جيرترود وأوفيليا. وهذا يدل على غنى النص."},{"i":"lt-26","s":17,"h":"تطبيق: نص واحد وكل العدسات","t":"mc","x":"أي قراءة ل Hamlet تركز على الذنب وعقدة أوديب؟ ؟ النسوية الثقافية فقط / النفسية الفرويدية / الشكلية / التاريخية . القراءة الفرويدية تربط التردد بأوديب والذنب."},{"i":"lt-26","s":19,"h":"كيف تكتب مقالا مقارنا","t":"learn","x":"خطة المقال 1) مقدمة: عرف المدرستين. 2) محور المقارنة: مصدر المعنى، دور المؤلف والقارئ، المنهج. 3) نقاط التشابه. 4) نقاط الاختلاف مع مثال. 5) خاتمة: لا توجد مدرسة وحدها كافية. ولا تنس الأسماء والتواريخ الصحيحة."},{"i":"lt-26","s":20,"h":"كيف تكتب مقالا مقارنا","t":"learn","x":"نصيحة امتحان اكتب لكل مدرسة: الفكرة، الأسماء، مثال تطبيقي، النقد الموجه إليها. استخدم عبارات ربط: بينما، في المقابل، بالإضافة إلى، كذلك. واستخدم عبارات حذرة في التفسيرات."},{"i":"lt-26","s":21,"h":"كيف تكتب مقالا مقارنا","t":"learn","x":"الملخص كل مدرسة عدسة. نختار أنسب عدسة أو نجمع بينها. المقارنة تكون على محاور: المعنى، المؤلف، القارئ، السياق، المنهج. وبكده تنتهي الرحلة الأساسية في هذا الكورس."},{"i":"lt-26","s":22,"h":"كيف تكتب مقالا مقارنا","t":"recall","x":"اذكر ثلاثة محاور تقارن بها بين مدرستين نقديتين. . مصدر المعنى، ودور المؤلف، ودور القارئ، أو السياق والمنهج المتبع."},{"i":"lt-26","s":23,"h":"كيف تكتب مقالا مقارنا","t":"write","x":"على نمط امتحانات الكلية: قارن بين الشكلانية والتاريخانية الجديدة (من 6 إلى 7 جمل). . تتفق المدرستان في أنهما تهتمان بدقة قراءة النص، لكنهما تختلفان في موقع المعنى. تعتبر الشكلانية النص كيانا مستقلا يفهم بسماته الداخلية مثل الصور والمفارقة والوزن، ولا تهتم بالسيرة والتاريخ. أما التاريخانية الجديدة، مع جرينبلات، فتراه جزءا من ثقافة عصره، وتقرأ النصوص الأدبية وغير الأدبية معا كمنتجات ثقافية. الأولى تبحث عن وحدة النص، والثانية عن السلطة والتبادل. وقد ظهرت الثانية كرد فعل على النقد الشكلي."},{"i":"lt-26","s":24,"h":"كيف تكتب مقالا مقارنا","t":"write","x":"على نمط امتحانات الكلية: قارن بين التحليل النفسي واستجابة القارئ (من 5 إلى 6 جمل). . كلاهما يهتم بالعقل والتجربة الشخصية، لكن التحليل النفسي يبحث عن اللاوعي في المؤلف أو الشخصيات أو النص، كما عند فرويد ويونغ. أما استجابة القارئ فتجعل القارئ مصدر المعنى، وبعض ممثليها مثل هولاند وبلايش اعتمدوا على علم النفس. فالأول يكشف ما تحت النص، والثاني يشرح اختلاف القراءات."}]};